        /// Push diagnostics are server-owned. Closing Raven's last live buffer
        /// for a URI must therefore replace its nonempty Problems entries with
        /// an empty publication; removing the URI from `WorldState::documents`
        /// alone does not clear the client collection.
        #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
        async fn did_close_publishes_empty_diagnostics_for_closed_uri() {
            let tmp = TempDir::new().unwrap();
            let path = tmp.path().join("close-me.R");
            let text = "definitely_missing_close_clear\n";
            std::fs::write(&path, text).unwrap();
            let uri = Url::from_file_path(path).unwrap();

            let (mut svc, mut socket) = LspService::new(super::super::Backend::new);
            let initialize = Request::build("initialize")
                .id(1)
                .params(serde_json::to_value(InitializeParams::default()).unwrap())
                .finish();
            let response = svc.ready().await.unwrap().call(initialize).await.unwrap();
            assert!(response.is_some_and(|response| response.is_ok()));
            let backend = svc.inner();
            {
                let mut state = backend.state.write().await;
                state.workspace_scan_complete = true;
                state.cross_file_config.packages_enabled = false;
                state.cross_file_config.on_demand_indexing_enabled = false;
                // Keep didOpen's own diagnostic task pending; didClose below
                // must cancel it before it can race the explicit stale marker.
                state.cross_file_config.revalidation_debounce_ms = 60_000;
            }

            backend
                .did_open(DidOpenTextDocumentParams {
                    text_document: TextDocumentItem {
                        uri: uri.clone(),
                        language_id: "r".into(),
                        version: 1,
                        text: text.into(),
                    },
                })
                .await;

            // Model the nonempty push diagnostics already owned by the client.
            // The close handler, not a fresh diagnostic computation, is what
            // must replace this marker with an empty list.
            backend
                .client
                .publish_diagnostics(
                    uri.clone(),
                    vec![Diagnostic::new_simple(
                        Range::default(),
                        "stale diagnostic".into(),
                    )],
                    None,
                )
                .await;
            let initial = tokio::time::timeout(Duration::from_secs(5), socket.next())
                .await
                .expect("seed diagnostic must publish")
                .expect("client socket must remain open");
            assert_eq!(initial.method(), "textDocument/publishDiagnostics");
            let initial: PublishDiagnosticsParams =
                serde_json::from_value(initial.params().unwrap().clone()).unwrap();
            assert_eq!(initial.uri, uri);
            assert!(
                !initial.diagnostics.is_empty(),
                "precondition: the open document must own nonempty diagnostics"
            );

            backend
                .did_close(DidCloseTextDocumentParams {
                    text_document: TextDocumentIdentifier { uri: uri.clone() },
                })
                .await;

            let cleared = tokio::time::timeout(Duration::from_secs(5), socket.next())
                .await
                .expect("close must clear diagnostics")
                .expect("client socket must remain open");
            assert_eq!(cleared.method(), "textDocument/publishDiagnostics");
            let cleared: PublishDiagnosticsParams =
                serde_json::from_value(cleared.params().unwrap().clone()).unwrap();
            assert_eq!(cleared.uri, uri);
            assert!(
                cleared.diagnostics.is_empty(),
                "closed document diagnostics must be cleared, got {:?}",
                cleared.diagnostics
            );
        }

        #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
        async fn diagnostic_worker_owning_publish_lock_orders_before_close_empty() {
            let tmp = TempDir::new().unwrap();
            let path = tmp.path().join("worker-first.R");
            std::fs::write(&path, "missing_worker_first\n").unwrap();
            let uri = Url::from_file_path(path).unwrap();
            let (mut svc, mut socket) = LspService::new(super::super::Backend::new);
            let initialize = Request::build("initialize")
                .id(1)
                .params(serde_json::to_value(InitializeParams::default()).unwrap())
                .finish();
            let response = svc.ready().await.unwrap().call(initialize).await.unwrap();
            assert!(response.is_some_and(|response| response.is_ok()));
            let backend = svc.inner();
            {
                let mut state = backend.state.write().await;
                state.workspace_scan_complete = true;
                state.cross_file_config.packages_enabled = false;
                state.cross_file_config.on_demand_indexing_enabled = false;
                state.cross_file_config.revalidation_debounce_ms = 60_000;
            }
            backend
                .did_open(DidOpenTextDocumentParams {
                    text_document: TextDocumentItem {
                        uri: uri.clone(),
                        language_id: "r".into(),
                        version: 1,
                        text: "missing_worker_first\n".into(),
                    },
                })
                .await;
            wait_until_pending(backend, &uri).await;
            let (pause, trigger) = {
                let state = backend.state.write().await;
                (
                    state
                        .diagnostics_post_publish_lock_test_pause
                        .arm(uri.clone()),
                    super::super::DiagnosticsTrigger::capture(&state, &uri),
                )
            };
            let worker = tokio::spawn(super::super::run_debounced_diagnostics(
                Arc::clone(&backend.state),
                backend.client.clone(),
                uri.clone(),
                0,
                trigger,
                None,
            ));
            tokio::time::timeout(Duration::from_secs(5), pause.wait_arrived())
                .await
                .expect("worker owns the publish lock");
            let close = backend.did_close(DidCloseTextDocumentParams {
                text_document: TextDocumentIdentifier { uri: uri.clone() },
            });
            tokio::pin!(close);
            tokio::select! {
                _ = &mut close => panic!("close committed while the worker owned the publish lock"),
                _ = tokio::time::sleep(Duration::from_millis(20)) => {}
            }
            let collector = tokio::spawn(async move {
                let mut publications = Vec::new();
                loop {
                    let message = tokio::time::timeout(Duration::from_secs(5), socket.next())
                        .await
                        .expect("ordered diagnostics publication must arrive")
                        .expect("client socket remains open");
                    if message.method() != "textDocument/publishDiagnostics" {
                        continue;
                    }
                    let params: PublishDiagnosticsParams =
                        serde_json::from_value(message.params().unwrap().clone()).unwrap();
                    if params.uri != uri {
                        continue;
                    }
                    let empty = params.diagnostics.is_empty();
                    publications.push(params);
                    if empty {
                        return publications;
                    }
                }
            });
            pause.release();
            worker.await.unwrap();
            close.await;
            let publications = collector.await.unwrap();
            assert!(
                publications.len() >= 2
                    && !publications[publications.len() - 2].diagnostics.is_empty()
                    && publications
                        .last()
                        .is_some_and(|params| params.diagnostics.is_empty()),
                "the exact order must end with worker nonempty then close empty; got {publications:?}"
            );
        }

        #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
        async fn close_owning_publish_lock_orders_before_stale_worker_declines() {
            let tmp = TempDir::new().unwrap();
            let path = tmp.path().join("close-first.R");
            std::fs::write(&path, "missing_close_first\n").unwrap();
            let uri = Url::from_file_path(path).unwrap();
            let (mut svc, mut socket) = LspService::new(super::super::Backend::new);
            let initialize = Request::build("initialize")
                .id(1)
                .params(serde_json::to_value(InitializeParams::default()).unwrap())
                .finish();
            let response = svc.ready().await.unwrap().call(initialize).await.unwrap();
            assert!(response.is_some_and(|response| response.is_ok()));
            let backend = svc.inner();
            {
                let mut state = backend.state.write().await;
                state.workspace_scan_complete = true;
                state.cross_file_config.packages_enabled = false;
                state.cross_file_config.on_demand_indexing_enabled = false;
                state.cross_file_config.revalidation_debounce_ms = 60_000;
            }
            backend
                .did_open(DidOpenTextDocumentParams {
                    text_document: TextDocumentItem {
                        uri: uri.clone(),
                        language_id: "r".into(),
                        version: 1,
                        text: "missing_close_first\n".into(),
                    },
                })
                .await;
            wait_until_pending(backend, &uri).await;
            let (worker_pause, close_pause, trigger) = {
                let state = backend.state.write().await;
                (
                    state.diagnostics_test_pause.arm(uri.clone()),
                    state
                        .did_close_post_commit_pre_publish_test_pause
                        .arm(uri.clone()),
                    super::super::DiagnosticsTrigger::capture(&state, &uri),
                )
            };
            let worker = tokio::spawn(super::super::run_debounced_diagnostics(
                Arc::clone(&backend.state),
                backend.client.clone(),
                uri.clone(),
                0,
                trigger,
                None,
            ));
            tokio::time::timeout(Duration::from_secs(5), worker_pause.wait_arrived())
                .await
                .expect("worker reaches its pre-lock barrier");
            let close = backend.did_close(DidCloseTextDocumentParams {
                text_document: TextDocumentIdentifier { uri: uri.clone() },
            });
            tokio::pin!(close);
            tokio::select! {
                _ = close_pause.wait_arrived() => {}
                _ = &mut close => panic!("close skipped its postcommit barrier"),
                _ = tokio::time::sleep(Duration::from_secs(5)) => {
                    panic!("close did not acquire the publish lock")
                }
            }
            worker_pause.release();
            tokio::time::sleep(Duration::from_millis(20)).await;
            assert!(
                !worker.is_finished(),
                "worker must wait behind the close lock"
            );
            close_pause.release();
            close.await;
            worker.await.unwrap();

            let mut publications = Vec::new();
            while let Ok(Some(message)) =
                tokio::time::timeout(Duration::from_millis(100), socket.next()).await
            {
                if message.method() == "textDocument/publishDiagnostics" {
                    let params: PublishDiagnosticsParams =
                        serde_json::from_value(message.params().unwrap().clone()).unwrap();
                    if params.uri == uri {
                        publications.push(params);
                    }
                }
            }
            assert_eq!(publications.len(), 1);
            assert!(publications[0].diagnostics.is_empty());
        }

