    // ============================================================================
    // LintConfig Parsing Tests
    // ============================================================================
    mod lint_config_parsing {
        use serde_json::json;

        #[test]
        fn parse_lint_config_returns_none_when_section_absent() {
            let settings = json!({});
            assert!(crate::backend::parse_lint_config(&settings, false).is_none());
        }

        #[test]
        fn parse_lint_config_reads_master_switch_and_line_length() {
            let settings = json!({
                "linting": {
                    "enabled": true,
                    "lineLength": 120
                }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert!(cfg.enabled);
            assert_eq!(cfg.line_length, 120);
        }

        #[test]
        fn parse_lint_config_clamps_line_length() {
            let settings = json!({ "linting": { "lineLength": 1 } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(cfg.line_length, 20);

            let settings = json!({ "linting": { "lineLength": 999_999 } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(cfg.line_length, 10_000);
        }

        #[test]
        fn parse_lint_config_clamps_before_u32_truncation() {
            // Regression: casting `u64 as u32` before clamping wraps values
            // above u32::MAX into a small number (u32::MAX + 5 -> 4), which
            // then clamps to the floor of 20 instead of the ceiling of
            // 10_000.
            let oversized = (u32::MAX as u64) + 5;
            let settings = json!({ "linting": { "lineLength": oversized } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(cfg.line_length, 10_000);
        }

        #[test]
        fn parse_lint_config_reads_assignment_operator_styles() {
            let settings = json!({ "linting": { "assignmentOperator": "=" } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(
                cfg.assignment_operator_style,
                crate::linting::AssignmentOperatorStyle::Equals
            );

            let settings = json!({ "linting": { "assignmentOperator": "<-" } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(
                cfg.assignment_operator_style,
                crate::linting::AssignmentOperatorStyle::LeftArrow
            );
        }

        #[test]
        fn parse_lint_config_reads_infix_continuation_styles() {
            use crate::linting::InfixContinuationStyle;
            for (value, expected) in [
                ("indented", InfixContinuationStyle::Indented),
                ("aligned", InfixContinuationStyle::Aligned),
                ("either", InfixContinuationStyle::Either),
            ] {
                let settings = json!({ "linting": { "infixContinuationStyle": value } });
                let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
                assert_eq!(cfg.infix_continuation_style, expected, "value {value:?}");
            }

            // Absent key keeps the default.
            let settings = json!({ "linting": { "lineLength": 100 } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(cfg.infix_continuation_style, InfixContinuationStyle::Either);
        }

        #[test]
        fn parse_lint_config_invalid_infix_continuation_style_falls_back_to_either() {
            use crate::linting::InfixContinuationStyle;
            // Unrecognized strings warn and fall back; mistyped non-string
            // values are skipped like every sibling string setting — either
            // way the default survives.
            for value in [
                json!("alignedd"),
                json!(42),
                json!(["aligned"]),
                json!(null),
            ] {
                let settings = json!({ "linting": { "infixContinuationStyle": value } });
                let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
                assert_eq!(
                    cfg.infix_continuation_style,
                    InfixContinuationStyle::Either,
                    "value {value:?}"
                );
            }
        }

        #[test]
        fn parse_lint_config_severities_off_disables_each_rule() {
            let settings = json!({
                "linting": {
                    "lineLengthSeverity": "off",
                    "trailingWhitespaceSeverity": "off",
                    "noTabSeverity": "off",
                    "trailingBlankLinesSeverity": "off",
                    "assignmentOperatorSeverity": "off",
                    "objectNameSeverity": "off",
                    "infixSpacesSeverity": "off",
                    "commentedCodeSeverity": "off",
                    "indentationSeverity": "off"
                }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(cfg.line_length_severity, None);
            assert_eq!(cfg.trailing_whitespace_severity, None);
            assert_eq!(cfg.no_tab_severity, None);
            assert_eq!(cfg.trailing_blank_lines_severity, None);
            assert_eq!(cfg.assignment_operator_severity, None);
            assert_eq!(cfg.object_name_severity, None);
            assert_eq!(cfg.infix_spaces_severity, None);
            assert_eq!(cfg.commented_code_severity, None);
            assert_eq!(cfg.indentation_severity, None);
        }

        #[test]
        fn parse_lint_config_reads_indentation_unit_and_clamps() {
            let settings = json!({ "linting": { "indentationUnit": 4 } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(cfg.indentation_unit, 4);

            // Above the ceiling is clamped down to 8.
            let settings = json!({ "linting": { "indentationUnit": 99 } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(cfg.indentation_unit, 8);

            // Zero is clamped up to 1 (the floor).
            let settings = json!({ "linting": { "indentationUnit": 0 } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(cfg.indentation_unit, 1);
        }

        #[test]
        fn parse_lint_config_reads_object_name_styles() {
            use crate::linting::ObjectNameStyle;
            let settings = json!({
                "linting": {
                    "objectNameStyleFunction": "camelCase",
                    "objectNameStyleVariable": "UPPER_CASE",
                    "objectNameStyleArgument": "any"
                }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(
                cfg.object_name_style_function,
                vec![ObjectNameStyle::CamelCase]
            );
            assert_eq!(
                cfg.object_name_style_variable,
                vec![ObjectNameStyle::UpperCase]
            );
            assert_eq!(cfg.object_name_style_argument, vec![ObjectNameStyle::Any]);
        }

        #[test]
        fn parse_lint_config_reads_object_name_style_arrays() {
            use crate::linting::ObjectNameStyle;
            let settings = json!({
                "linting": {
                    "objectNameStyleFunction": ["snake_case", "camelCase"],
                    "objectNameStyleVariable": ["lowercase"],
                    "objectNameStyleArgument": ["dotted.case", "UPPER_CASE"]
                }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(
                cfg.object_name_style_function,
                vec![ObjectNameStyle::SnakeCase, ObjectNameStyle::CamelCase]
            );
            assert_eq!(
                cfg.object_name_style_variable,
                vec![ObjectNameStyle::Lowercase]
            );
            assert_eq!(
                cfg.object_name_style_argument,
                vec![ObjectNameStyle::DottedCase, ObjectNameStyle::UpperCase]
            );
        }

        #[test]
        fn parse_lint_config_unrecognized_object_name_style_disables_kind() {
            // With no valid style elements and no regexes, the kind resolves
            // to empty lists, which `is_disabled` treats as off — the same
            // fail-safe as the historical `[any]` fallback.
            let settings = json!({
                "linting": { "objectNameStyleFunction": "kebab-case" }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert!(cfg.object_name_style_function.is_empty());
            assert!(cfg.object_name_regexes_function.is_empty());
        }

        #[test]
        fn parse_lint_config_unrecognized_style_with_regexes_keeps_regexes() {
            // An all-invalid style list must not discard valid regexes for
            // the same kind: the kind becomes regex-only instead of disabled.
            let settings = json!({
                "linting": {
                    "objectNameStyleFunction": ["typo"],
                    "objectNameRegexesFunction": ["^Foo$"]
                }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert!(cfg.object_name_style_function.is_empty());
            assert_eq!(
                cfg.object_name_regexes_function
                    .iter()
                    .map(|regex| regex.source())
                    .collect::<Vec<_>>(),
                vec!["^Foo$"]
            );
        }

        #[test]
        fn parse_lint_config_skips_invalid_object_name_style_array_elements() {
            use crate::linting::ObjectNameStyle;
            let settings = json!({
                "linting": {
                    "objectNameStyleFunction": ["snake_case", "kebab-case", "camelCase"],
                    "objectNameStyleVariable": ["kebab-case", 42],
                    "objectNameStyleArgument": []
                }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(
                cfg.object_name_style_function,
                vec![ObjectNameStyle::SnakeCase, ObjectNameStyle::CamelCase]
            );
            // No valid elements and no regexes: empty means the kind is
            // disabled (see `parse_object_name_kind_settings`).
            assert!(cfg.object_name_style_variable.is_empty());
            assert!(cfg.object_name_style_argument.is_empty());
        }

        #[test]
        fn parse_lint_config_reads_object_name_regexes() {
            let settings = json!({
                "linting": {
                    "objectNameRegexesFunction": ["^x", "Bar"],
                    "objectNameRegexesVariable": ["\\\\.hidden"],
                    "objectNameRegexesArgument": ["[0-9]+$"]
                }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(
                cfg.object_name_regexes_function
                    .iter()
                    .map(|regex| regex.source())
                    .collect::<Vec<_>>(),
                vec!["^x", "Bar"]
            );
            assert_eq!(
                cfg.object_name_regexes_variable
                    .iter()
                    .map(|regex| regex.source())
                    .collect::<Vec<_>>(),
                vec!["\\\\.hidden"]
            );
            assert_eq!(
                cfg.object_name_regexes_argument
                    .iter()
                    .map(|regex| regex.source())
                    .collect::<Vec<_>>(),
                vec!["[0-9]+$"]
            );
        }

        #[test]
        fn parse_lint_config_rejects_empty_and_invalid_object_name_regexes() {
            let settings = json!({
                "linting": {
                    "objectNameRegexesFunction": ["", "^ok$", "(?=bad)", "   "]
                }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert_eq!(
                cfg.object_name_regexes_function
                    .iter()
                    .map(|regex| regex.source())
                    .collect::<Vec<_>>(),
                vec!["^ok$", "   "]
            );
        }

        #[test]
        fn parse_lint_config_invalid_regex_only_mode_retains_default_style() {
            use crate::linting::ObjectNameStyle;
            let settings = json!({
                "linting": {
                    "objectNameStyleFunction": [],
                    "objectNameRegexesFunction": ["(?=bad)"],
                    "objectNameStyleVariable": [],
                    "objectNameRegexesVariable": ["", 42],
                    "objectNameStyleArgument": [],
                    "objectNameRegexesArgument": "not-an-array"
                }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();

            // The restored fallback matches `LintConfig::default()`'s per-kind
            // styles: snake_case + symbols (lintr's default `styles`).
            let default_styles = vec![ObjectNameStyle::SnakeCase, ObjectNameStyle::Symbols];
            assert_eq!(cfg.object_name_style_function, default_styles);
            assert_eq!(cfg.object_name_style_variable, default_styles);
            assert_eq!(cfg.object_name_style_argument, default_styles);
            assert!(cfg.object_name_regexes_function.is_empty());
            assert!(cfg.object_name_regexes_variable.is_empty());
            assert!(cfg.object_name_regexes_argument.is_empty());
        }

        #[test]
        fn parse_lint_config_explicit_empty_regex_only_mode_stays_disabled() {
            let settings = json!({
                "linting": {
                    "objectNameStyleFunction": [],
                    "objectNameRegexesFunction": []
                }
            });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert!(cfg.object_name_style_function.is_empty());
            assert!(cfg.object_name_regexes_function.is_empty());
        }

        #[test]
        fn parse_lint_config_non_object_returns_none() {
            let settings = json!({ "linting": 42 });
            assert!(crate::backend::parse_lint_config(&settings, false).is_none());
        }

        // ============================================================================
        // Tri-state `enabled` resolution (#281)
        // ============================================================================

        #[test]
        fn parse_lint_config_client_false_overrides_lintr_discovery() {
            // Regression for #281: an explicit client `enabled = false` must
            // remain false even when a .lintr is the discovered project config.
            let settings = json!({ "linting": { "enabled": false } });
            let cfg = crate::backend::parse_lint_config(&settings, true).unwrap();
            assert!(!cfg.enabled, "client false must win over .lintr discovery");
        }

        #[test]
        fn parse_lint_config_auto_default_no_project_off() {
            let settings = json!({ "linting": { "enabled": "auto" } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert!(!cfg.enabled);
        }

        #[test]
        fn parse_lint_config_auto_with_lintr_on() {
            let settings = json!({ "linting": { "enabled": "auto" } });
            let cfg = crate::backend::parse_lint_config(&settings, true).unwrap();
            assert!(cfg.enabled);
        }

        #[test]
        fn parse_lint_config_auto_no_section_with_discovered_true_is_on() {
            // Pure-function contract: given lintr_discovered = true and no
            // linting section, return Some(default config) with enabled = true.
            // (End-to-end, a content-free `.lintr` no longer reaches here with
            // `true` — `config_file::lintr_expresses_linting` gates that — but
            // the function must remain defensively correct for any caller.)
            let settings = json!({});
            let cfg = crate::backend::parse_lint_config(&settings, true).unwrap();
            assert!(cfg.enabled);
            assert_eq!(
                cfg.line_length,
                crate::linting::LintConfig::default().line_length
            );
        }

        #[test]
        fn parse_lint_config_no_section_no_lintr_returns_none() {
            // No linting section AND no .lintr discovered → keep the old
            // behavior of returning None so the caller can decide a default.
            let settings = json!({});
            assert!(crate::backend::parse_lint_config(&settings, false).is_none());
        }

        #[test]
        fn parse_lint_config_string_on_off() {
            let on = json!({ "linting": { "enabled": "on" } });
            let off = json!({ "linting": { "enabled": "off" } });
            assert!(
                crate::backend::parse_lint_config(&on, false)
                    .unwrap()
                    .enabled
            );
            assert!(
                !crate::backend::parse_lint_config(&off, true)
                    .unwrap()
                    .enabled
            );
        }

        #[test]
        fn parse_lint_config_string_true_false_backcompat() {
            let t = json!({ "linting": { "enabled": "true" } });
            let f = json!({ "linting": { "enabled": "false" } });
            assert!(
                crate::backend::parse_lint_config(&t, false)
                    .unwrap()
                    .enabled
            );
            assert!(!crate::backend::parse_lint_config(&f, true).unwrap().enabled);
        }

        #[test]
        fn parse_lint_config_bool_backcompat() {
            let t = json!({ "linting": { "enabled": true } });
            let f = json!({ "linting": { "enabled": false } });
            assert!(
                crate::backend::parse_lint_config(&t, false)
                    .unwrap()
                    .enabled
            );
            assert!(!crate::backend::parse_lint_config(&f, true).unwrap().enabled);
        }

        #[test]
        fn parse_lint_config_invalid_string_warns_falls_back_to_auto() {
            let settings = json!({ "linting": { "enabled": "yes" } });
            // With lintr_discovered = false, Auto resolves to off.
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert!(!cfg.enabled);
            // With lintr_discovered = true, Auto resolves to on.
            let cfg = crate::backend::parse_lint_config(&settings, true).unwrap();
            assert!(cfg.enabled);
        }

        #[test]
        fn parse_lint_config_invalid_json_types_fall_back_to_auto() {
            for bad in [json!(42), json!([]), json!({})] {
                let settings = json!({ "linting": { "enabled": bad } });
                // Auto with no lintr_discovered → off.
                let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
                assert!(!cfg.enabled, "expected off for invalid enabled value {bad}");
            }
        }

        #[test]
        fn parse_lint_config_null_silent_falls_back_to_auto() {
            let settings = json!({ "linting": { "enabled": null } });
            let cfg = crate::backend::parse_lint_config(&settings, false).unwrap();
            assert!(!cfg.enabled);
            let cfg = crate::backend::parse_lint_config(&settings, true).unwrap();
            assert!(cfg.enabled);
        }
    }

