    #[tokio::test]
    async fn workspace_scan_open_parent_wins_for_forward_only_open_child() {
        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("w1")).unwrap();
        fs::create_dir(tmp.path().join("w2")).unwrap();
        fs::write(
            tmp.path().join("A.R"),
            "# raven: cd w1\nsource(\"../C.R\")\n",
        )
        .unwrap();
        fs::write(tmp.path().join("C.R"), "source(\"helper.R\")\n").unwrap();
        fs::write(tmp.path().join("w1/helper.R"), "old_helper <- 1\n").unwrap();
        fs::write(tmp.path().join("w2/helper.R"), "new_helper <- 1\n").unwrap();

        let root = Url::from_file_path(tmp.path()).unwrap();
        let a_uri = Url::from_file_path(tmp.path().join("A.R")).unwrap();
        let c_uri = Url::from_file_path(tmp.path().join("C.R")).unwrap();
        let old_helper_uri = Url::from_file_path(tmp.path().join("w1/helper.R")).unwrap();
        let new_helper_uri = Url::from_file_path(tmp.path().join("w2/helper.R")).unwrap();
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: root,
                    name: "t".into(),
                }]),
                initialization_options: Some(serde_json::json!({
                    "crossFile": { "indexWorkspace": false },
                    "packages": { "enabled": false }
                })),
                ..Default::default()
            })
            .await
            .unwrap();
        open_doc(
            backend,
            &a_uri,
            "r",
            1,
            "# raven: cd w2\nsource(\"../C.R\")\n",
        )
        .await;
        open_doc(backend, &c_uri, "r", 1, "source(\"helper.R\")\n").await;

        {
            let mut state = backend.state.write().await;
            state.cross_file_config.index_workspace = true;
            state.advance_workspace_scan_generation();
        }
        run_workspace_scan_until_current(&backend.state)
            .await
            .expect("workspace scan should apply");

        let state = backend.state.read().await;
        assert_eq!(
            state
                .get_enriched_metadata(&c_uri)
                .and_then(|metadata| metadata.inherited_working_directory.clone()),
            Some(tmp.path().join("w2").to_string_lossy().to_string()),
            "authoritative open A must beat the duplicate scanned A parent"
        );
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&c_uri)
                .iter()
                .any(|edge| edge.to == new_helper_uri)
        );
        assert!(
            !state
                .cross_file_graph
                .get_dependencies(&c_uri)
                .iter()
                .any(|edge| edge.to == old_helper_uri)
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn workspace_exclusion_reload_reindexes_newly_included_files() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        fs::create_dir(tmp.path().join("generated")).unwrap();
        let generated_path = tmp.path().join("generated").join("helper.R");
        fs::write(&generated_path, "generated_fn <- function() 1\n").unwrap();
        fs::write(
            tmp.path().join("raven.toml"),
            "[workspace]\nexclude = [\"generated/**\"]\n",
        )
        .unwrap();
        let generated_uri = Url::from_file_path(&generated_path).unwrap();

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();

        {
            let state = backend.state.read().await;
            assert!(state.workspace_exclusions.is_excluded_uri(&generated_uri));
            assert!(
                state.workspace_index.get(&generated_uri).is_none(),
                "precondition: excluded file must not already be indexed"
            );
        }

        fs::write(tmp.path().join("raven.toml"), "[workspace]\nexclude = []\n").unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: Url::from_file_path(tmp.path().join("raven.toml")).unwrap(),
                    typ: FileChangeType::CHANGED,
                }],
            })
            .await;

        let state = backend.state.read().await;
        assert!(
            !state.workspace_exclusions.is_excluded_uri(&generated_uri),
            "reload must pick up the removed exclusion"
        );
        assert!(
            state.workspace_index.get(&generated_uri).is_some(),
            "newly re-included file must be merged into the unified workspace index"
        );
        assert!(
            state.workspace_index.get_metadata(&generated_uri).is_some(),
            "newly re-included file must have an artifact projection"
        );
        assert!(
            state
                .workspace_index
                .artifact_uris()
                .contains(&generated_uri),
            "newly re-included file must be owned by the workspace scan"
        );
    }

