    /// If an external project config becomes malformed, it must stop being
    /// active and reset the parsed settings that came from that project layer.
    /// Separate watcher-registration tests cover keeping external config
    /// directories watched so a later fix is not missed.
    #[tokio::test]
    async fn watched_files_reload_clears_load_failed_external_config_layer() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let home = TempDir::new().unwrap();
        let workspace = home.path().join("project");
        fs::create_dir(&workspace).unwrap();
        let toml_path = home.path().join("raven.toml");
        fs::write(&toml_path, "[linting]\nenabled = true\nlineLength = 120\n").unwrap();
        let root = Url::from_file_path(&workspace).unwrap();

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: root,
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();

        {
            let state = backend.state.read().await;
            assert_eq!(
                state.project_config_path.as_deref(),
                Some(toml_path.as_path())
            );
            assert!(state.lint_config.enabled);
            assert_eq!(state.lint_config.line_length, 120);
        }

        fs::write(&toml_path, "not valid = = toml [[[\n").unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: Url::from_file_path(&toml_path).unwrap(),
                    typ: FileChangeType::CHANGED,
                }],
            })
            .await;

        let state = backend.state.read().await;
        assert!(
            state.project_config_path.is_none(),
            "load failure must clear the active project config"
        );
        assert!(state.raw_project_settings.is_none());
        assert_eq!(state.lint_config.line_length, 80);
    }

    /// The watched-files reload path must update `state.project_config_path`
    /// so the subsequent `raven/projectConfigLoaded` notification carries
    /// the live value (rather than the path captured at initialize time).
    /// This complements the initialize-time test
    /// `initialize_loads_raven_toml_from_workspace_root`.
    #[tokio::test]
    async fn watched_files_reload_updates_project_config_path_for_notification() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        let root = Url::from_file_path(tmp.path()).unwrap();

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: root.clone(),
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();
        // No config at initialize time.
        assert!(backend.state.read().await.project_config_path.is_none());

        // Create raven.toml; watched_files reload should pick it up and
        // populate project_config_path so the notification helper has a
        // fresh value to emit.
        let toml_path = tmp.path().join("raven.toml");
        fs::write(&toml_path, "[linting]\nenabled = true\n").unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: Url::from_file_path(&toml_path).unwrap(),
                    typ: FileChangeType::CREATED,
                }],
            })
            .await;
        assert_eq!(
            backend.state.read().await.project_config_path.as_deref(),
            Some(toml_path.as_path())
        );

        // Delete raven.toml; watched_files reload should clear the path
        // so the notification helper emits the cleared form (`path: null`).
        std::fs::remove_file(&toml_path).unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: Url::from_file_path(&toml_path).unwrap(),
                    typ: FileChangeType::DELETED,
                }],
            })
            .await;
        assert!(backend.state.read().await.project_config_path.is_none());
    }

    #[tokio::test]
    async fn watched_files_reload_notifies_project_config_loaded_over_socket() {
        use futures_util::{SinkExt, StreamExt};
        use serde_json::json;
        use std::time::Duration;
        use tower::{Service, ServiceExt};
        use tower_lsp::jsonrpc::{Request, Response};
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        let root = Url::from_file_path(tmp.path()).unwrap();

        let (mut svc, socket) = tower_lsp::LspService::new(Backend::new);
        let initialize = Request::build("initialize")
            .id(1)
            .params(
                serde_json::to_value(InitializeParams {
                    workspace_folders: Some(vec![WorkspaceFolder {
                        uri: root,
                        name: "t".into(),
                    }]),
                    initialization_options: Some(json!({
                        "crossFile": { "indexWorkspace": false },
                        "packages": { "enabled": false },
                    })),
                    ..Default::default()
                })
                .unwrap(),
            )
            .finish();
        let response = svc.ready().await.unwrap().call(initialize).await.unwrap();
        assert!(response.is_some_and(|response| response.is_ok()));

        let toml_path = tmp.path().join("raven.toml");
        fs::write(&toml_path, "[linting]\nenabled = true\n").unwrap();

        let (mut request_stream, mut response_sink) = socket.split();
        macro_rules! expect_project_config_loaded {
            ($change_type:expr, $expected_path:expr, $expected_source:expr) => {{
                let changed = svc
                    .inner()
                    .did_change_watched_files(DidChangeWatchedFilesParams {
                        changes: vec![FileEvent {
                            uri: Url::from_file_path(&toml_path).unwrap(),
                            typ: $change_type,
                        }],
                    });
                tokio::pin!(changed);
                let mut changed_done = false;
                let mut saw_notification = false;

                loop {
                    if changed_done && saw_notification {
                        break;
                    }

                    let request = if changed_done {
                        tokio::time::timeout(Duration::from_secs(5), request_stream.next())
                            .await
                            .expect("watched-files reload should send raven/projectConfigLoaded")
                    } else {
                        tokio::select! {
                            () = &mut changed => {
                                changed_done = true;
                                continue;
                            }
                            request = tokio::time::timeout(Duration::from_secs(5), request_stream.next()) => {
                                request.expect("watched-files reload should send client requests or project config notification")
                            }
                        }
                    }
                    .expect("client socket should remain open");

                    if request.method() == "raven/projectConfigLoaded" {
                        let payload = request.params().expect("project config payload");
                        assert_eq!(payload["path"], $expected_path);
                        assert_eq!(payload["source"], $expected_source);
                        saw_notification = true;
                    }

                    if let Some(id) = request.id().cloned() {
                        response_sink
                            .send(Response::from_ok(id, serde_json::Value::Null))
                            .await
                            .unwrap();
                    }
                }
            }};
        }

        expect_project_config_loaded!(
            FileChangeType::CREATED,
            serde_json::Value::String(toml_path.display().to_string()),
            serde_json::Value::String("raven.toml".into())
        );

        fs::remove_file(&toml_path).unwrap();
        expect_project_config_loaded!(
            FileChangeType::DELETED,
            serde_json::Value::Null,
            serde_json::Value::Null
        );
    }

    /// `did_change_watched_files` publishes diagnostics for every open
    /// document on a `raven.toml` reload. With the parallel JoinSet
    /// driver, all spawned publish tasks must be joined before the
    /// handler returns — otherwise a later `did_change` could race a
    /// still-running reload publish and corrupt monotonic-version
    /// ordering.
    ///
    /// We exercise 12 open `.R` files (above the concurrency cap of 8).
    /// The reload's reconciliation helper marks every open URI for
    /// force-republish (counter increment); a successful publish
    /// decrements that counter via `try_consume_publish`. Asserting that
    /// every URI's `force_republish_count_for_test == 0` after the
    /// handler returns is a stronger signal than checking
    /// `last_published_version` — the gate's prior-publish state from
    /// `did_open` would already make `can_publish(uri, 1)` return
    /// false, so that observable could pass without the reload doing
    /// anything.
    #[tokio::test]
    async fn watched_files_reload_publishes_all_open_documents_in_parallel() {
        use tower_lsp::lsp_types::{
            DidChangeWatchedFilesParams, DidOpenTextDocumentParams, FileChangeType, FileEvent,
            TextDocumentItem,
        };

        let tmp = TempDir::new().unwrap();
        fs::write(
            tmp.path().join("raven.toml"),
            "[linting]\nenabled = true\nlineLength = 100\n",
        )
        .unwrap();

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();

        const N: usize = 12;
        let mut uris: Vec<Url> = Vec::with_capacity(N);
        for i in 0..N {
            let p = tmp.path().join(format!("file_{i}.R"));
            fs::write(&p, "x <- 1\n").unwrap();
            let uri = Url::from_file_path(&p).unwrap();
            backend
                .did_open(DidOpenTextDocumentParams {
                    text_document: TextDocumentItem {
                        uri: uri.clone(),
                        language_id: "r".into(),
                        version: 1,
                        text: "x <- 1\n".into(),
                    },
                })
                .await;
            uris.push(uri);
        }

        // Sanity: pre-reload, no outstanding force-republish markers — the
        // reload is the only path under test that will mark and then
        // consume them.
        {
            let state = backend.state.read().await;
            for uri in &uris {
                assert_eq!(
                    state.diagnostics_gate.force_republish_count_for_test(uri),
                    0,
                    "unexpected pre-reload force-republish marker for {uri}"
                );
            }
        }

        // Edit raven.toml and trigger a reload.
        fs::write(
            tmp.path().join("raven.toml"),
            "[linting]\nenabled = true\nlineLength = 140\n",
        )
        .unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: Url::from_file_path(tmp.path().join("raven.toml")).unwrap(),
                    typ: FileChangeType::CHANGED,
                }],
            })
            .await;

        // After the handler returns, every URI's force-republish marker
        // (set by the reconciliation helper) must have been consumed by
        // a successful `try_consume_publish` — a stuck or un-awaited
        // task would leave its URI's counter at 1.
        let state = backend.state.read().await;
        for uri in &uris {
            assert_eq!(
                state.diagnostics_gate.force_republish_count_for_test(uri),
                0,
                "reload's parallel publish driver left an outstanding force-republish marker for {uri}",
            );
        }
    }

    /// Characterization test for the watched-files CREATED/CHANGED async
    /// disk-read pass: a disk edit to a CLOSED file must update the
    /// dependency graph and the cross-file workspace index from disk
    /// content. Written before extracting the shared single-file resync
    /// primitive (issue #558) to pin the current behavior through the
    /// refactor.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_file_change_updates_graph_and_index_from_disk() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helper.R"), "helper_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        fs::write(
            tmp.path().join("main.R"),
            "source(\"helper.R\")\nhelper_fn()\n",
        )
        .unwrap();
        let (svc, main_uri) =
            open_in_workspace(&tmp, "main.R", "r", "source(\"helper.R\")\nhelper_fn()\n").await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(tmp.path().join("helper.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        // Sanity: opening main.R created the main -> helper edge.
        {
            let state = backend.state.read().await;
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&main_uri)
                    .iter()
                    .any(|e| e.to == helper_uri),
                "did_open must add the main -> helper edge"
            );
        }

        // External (closed-file) disk edit: helper.R gains a source() edge.
        fs::write(
            tmp.path().join("helper.R"),
            "source(\"extra.R\")\nhelper_fn <- function() 1\n",
        )
        .unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: helper_uri.clone(),
                    typ: FileChangeType::CHANGED,
                }],
            })
            .await;

        // The graph mutation happens in the spawned async disk-read pass.
        let updated = wait_for_state(backend, 5_000, |state| {
            state
                .cross_file_graph
                .get_dependencies(&helper_uri)
                .iter()
                .any(|e| e.to == extra_uri)
        })
        .await;
        assert!(
            updated,
            "watched CHANGED event must add the helper -> extra edge from disk content"
        );
        let state = backend.state.read().await;
        let meta = state
            .workspace_index
            .get_metadata(&helper_uri)
            .expect("workspace index must hold disk-derived metadata for the changed file");
        assert_eq!(
            meta.sources.len(),
            1,
            "index metadata must reflect the new on-disk source() call"
        );
    }

    /// Characterization test for the watched-files DELETED branch: deleting
    /// a closed file must drop its graph edges (including the mirror in an
    /// open parent's forward list) and its workspace-index entry, and the
    /// open dependent's force-republish marker must be consumed by the
    /// synchronous publish before the handler returns. Pins current
    /// behavior ahead of the issue #558 extraction.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_file_deleted_removes_graph_edges_and_index_entry() {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};

        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helper.R"), "helper_fn <- function() 1\n").unwrap();
        fs::write(
            tmp.path().join("main.R"),
            "source(\"helper.R\")\nhelper_fn()\n",
        )
        .unwrap();
        let (svc, main_uri) =
            open_in_workspace(&tmp, "main.R", "r", "source(\"helper.R\")\nhelper_fn()\n").await;
        let backend = svc.inner();
        let helper_uri = Url::from_file_path(tmp.path().join("helper.R")).unwrap();

        // The undefined-variable collector defers all diagnostics until the
        // workspace scan completes (Auto backward-dependency mode); the test
        // harness never runs `initialized`, so mark the scan complete.
        backend.state.write().await.workspace_scan_complete = true;

        // Sanity: the edge exists and helper_fn resolves (no diagnostics).
        {
            let state = backend.state.read().await;
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&main_uri)
                    .iter()
                    .any(|e| e.to == helper_uri),
                "did_open must add the main -> helper edge"
            );
            assert!(
                snapshot_diagnostics(&state, &main_uri).is_empty(),
                "helper_fn must resolve through the source() edge before deletion"
            );
        }

        fs::remove_file(tmp.path().join("helper.R")).unwrap();
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: helper_uri.clone(),
                    typ: FileChangeType::DELETED,
                }],
            })
            .await;

        // DELETED-only batches mutate the graph synchronously, so the
        // post-handler state is final: edges gone in both directions, index
        // entry gone, and the dependent's force-republish marker consumed by
        // the synchronous publish loop.
        let state = backend.state.read().await;
        assert!(
            !state
                .cross_file_graph
                .get_dependencies(&main_uri)
                .iter()
                .any(|e| e.to == helper_uri),
            "deletion must remove the main -> helper edge"
        );
        assert!(
            state
                .cross_file_graph
                .get_dependents(&helper_uri)
                .is_empty(),
            "deletion must clear the deleted file's backward edges"
        );
        assert!(
            state.workspace_index.get_metadata(&helper_uri).is_none(),
            "deletion must invalidate the workspace-index entry"
        );
        assert_eq!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&main_uri),
            0,
            "the dependent's force-republish marker must be consumed before the handler returns"
        );
        assert!(
            !snapshot_diagnostics(&state, &main_uri).is_empty(),
            "helper_fn must be flagged once the sourced file is gone"
        );
    }

    /// Issue #567: a live buffer opened with casing that differs from the
    /// on-disk spelling must still behave as the canonical graph URI. The test
    /// constructs that LSP state directly, so it is non-vacuous on
    /// case-sensitive hosts where a real editor normally could not open the
    /// wrong-case path from disk.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn wrong_case_alias_edit_revalidates_parent_and_supplies_live_content() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("child.r"), "child_fn <- function() 1\n").unwrap();
        let parent = "source(\"child.r\")\nchild_fn()\nlive_fn()\n";
        fs::write(tmp.path().join("parent.R"), parent).unwrap();

        let (svc, parent_uri) = open_in_workspace(&tmp, "parent.R", "r", parent).await;
        let backend = svc.inner();
        let child_real_uri = Url::from_file_path(tmp.path().join("child.r")).unwrap();
        let child_alias_uri = Url::from_file_path(tmp.path().join("child.R")).unwrap();
        {
            let mut state = backend.state.write().await;
            state.workspace_scan_complete = true;
            state.cross_file_config.revalidation_debounce_ms = 60_000;
        }

        open_doc(
            backend,
            &child_alias_uri,
            "r",
            1,
            "child_fn <- function() 1\n",
        )
        .await;
        let parent_force_before_change = {
            let state = backend.state.read().await;
            assert_eq!(
                state.open_document_uri_for_authoritative_uri(&child_real_uri),
                Some(child_alias_uri.clone()),
                "real on-disk spelling must resolve to the wrong-case open buffer"
            );
            assert!(
                !snapshot_diagnostics(&state, &parent_uri).is_empty(),
                "precondition: live_fn is undefined before the alias buffer defines it"
            );
            state
                .diagnostics_gate
                .force_republish_count_for_test(&parent_uri)
        };

        change_doc(
            backend,
            &child_alias_uri,
            2,
            "child_fn <- function() 1\nlive_fn <- function() 2\n",
        )
        .await;

        let state = backend.state.read().await;
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&parent_uri)
                .iter()
                .any(|edge| edge.to == child_real_uri),
            "parent edge must remain keyed by the real on-disk spelling"
        );
        assert!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&parent_uri)
                > parent_force_before_change,
            "editing the alias buffer must schedule the canonical dependent parent"
        );
        assert!(
            snapshot_diagnostics(&state, &parent_uri).is_empty(),
            "parent scope must see live content from the wrong-case alias buffer"
        );
    }

    /// Issue #567: watched-file resync for the canonical spelling must be
    /// vetoed while a wrong-case alias buffer is open, because the buffer is
    /// authoritative for that on-disk file.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_changed_for_canonical_spelling_is_vetoed_while_alias_open() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("child.r"), "child_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        let (svc, _parent_uri) =
            open_in_workspace(&tmp, "parent.R", "r", "source(\"child.r\")\n").await;
        let backend = svc.inner();
        let child_real_uri = Url::from_file_path(tmp.path().join("child.r")).unwrap();
        let child_alias_uri = Url::from_file_path(tmp.path().join("child.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        open_doc(
            backend,
            &child_alias_uri,
            "r",
            1,
            "source(\"extra.R\")\nchild_fn <- function() 1\n",
        )
        .await;
        {
            let state = backend.state.read().await;
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&child_real_uri)
                    .iter()
                    .any(|edge| edge.to == extra_uri),
                "alias open must mirror live source() edges onto the canonical graph URI"
            );
        }

        fs::write(tmp.path().join("child.r"), "child_fn <- function() 1\n").unwrap();
        let outcome = resync_file_from_disk(
            &backend.state,
            &child_real_uri,
            None,
            None,
            true,
            None,
            ResyncCommitMode::Immediate,
        )
        .await;
        assert!(
            matches!(outcome, ResyncOutcome::Vetoed),
            "direct resync of the canonical URI must veto while alias-open"
        );
        send_watched_change(backend, &child_real_uri).await;
        tokio::time::sleep(std::time::Duration::from_millis(200)).await;

        let state = backend.state.read().await;
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&child_real_uri)
                .iter()
                .any(|edge| edge.to == extra_uri),
            "watched CHANGED must not replace alias-buffer graph state with disk content"
        );
    }

    /// Issue #567: closing the alias removes the alias map; later watched
    /// events for the canonical spelling converge from disk normally.
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn alias_map_drops_on_close_and_later_watched_events_resync() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("child.r"), "child_fn <- function() 1\n").unwrap();
        fs::write(tmp.path().join("extra.R"), "extra_fn <- function() 2\n").unwrap();
        let (svc, _parent_uri) =
            open_in_workspace(&tmp, "parent.R", "r", "source(\"child.r\")\n").await;
        let backend = svc.inner();
        let child_real_uri = Url::from_file_path(tmp.path().join("child.r")).unwrap();
        let child_alias_uri = Url::from_file_path(tmp.path().join("child.R")).unwrap();
        let extra_uri = Url::from_file_path(tmp.path().join("extra.R")).unwrap();

        open_doc(
            backend,
            &child_alias_uri,
            "r",
            1,
            "child_fn <- function() 1\n",
        )
        .await;
        close_doc(backend, &child_alias_uri).await;
        {
            let state = backend.state.read().await;
            assert!(
                state.open_document_aliases.is_empty(),
                "closing the alias buffer must tear down the alias map"
            );
            assert!(
                state
                    .open_document_uri_for_authoritative_uri(&child_real_uri)
                    .is_none(),
                "canonical spelling must no longer be treated as open"
            );
        }

        let closed_resync_finished = wait_for_state(backend, 5_000, |state| {
            state
                .workspace_index
                .get_metadata(&child_real_uri)
                .is_some()
        })
        .await;
        assert!(
            closed_resync_finished,
            "close resync must restore canonical closed-file state"
        );

        fs::write(
            tmp.path().join("child.r"),
            "source(\"extra.R\")\nchild_fn <- function() 1\n",
        )
        .unwrap();
        send_watched_change(backend, &child_real_uri).await;

        let resynced = wait_for_state(backend, 5_000, |state| {
            state
                .cross_file_graph
                .get_dependencies(&child_real_uri)
                .iter()
                .any(|edge| edge.to == extra_uri)
        })
        .await;
        assert!(
            resynced,
            "after alias close, watched CHANGED must resync canonical disk content normally"
        );
    }

    /// A watcher event on the exact opened symlink spelling is the
    /// reconciliation signal for a post-open retarget.
    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_open_symlink_retarget_atomically_moves_alias_and_graph_authority() {
        let tmp = TempDir::new().unwrap();
        let first = tmp.path().join("first.R");
        let second = tmp.path().join("second.R");
        let link = tmp.path().join("link.R");
        let extra = tmp.path().join("extra.R");
        fs::write(&first, "first_disk <- 1\n").unwrap();
        fs::write(&second, "second_disk <- 1\n").unwrap();
        fs::write(&extra, "extra <- 1\n").unwrap();
        std::os::unix::fs::symlink("first.R", &link).unwrap();
        let (svc, _seed_uri) = open_in_workspace(&tmp, "extra.R", "r", "extra <- 1\n").await;
        let backend = svc.inner();
        let link_uri = Url::from_file_path(&link).unwrap();
        let first_uri = Url::from_file_path(&first).unwrap();
        let second_uri = Url::from_file_path(&second).unwrap();
        let extra_uri = Url::from_file_path(&extra).unwrap();
        open_doc(
            backend,
            &link_uri,
            "r",
            1,
            "source(\"extra.R\")\nlive <- 1\n",
        )
        .await;
        assert_eq!(
            backend
                .state
                .read()
                .await
                .open_document_uri_for_authoritative_uri(&first_uri),
            Some(link_uri.clone())
        );

        fs::remove_file(&link).unwrap();
        std::os::unix::fs::symlink("second.R", &link).unwrap();
        send_watched_change(backend, &link_uri).await;

        let state = backend.state.read().await;
        assert_eq!(
            state.open_document_uri_for_authoritative_uri(&second_uri),
            Some(link_uri.clone())
        );
        assert_eq!(
            state.open_document_uri_for_authoritative_uri(&first_uri),
            None
        );
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&second_uri)
                .iter()
                .any(|edge| edge.to == extra_uri),
            "the new target must receive the live buffer graph projection"
        );
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&first_uri)
                .is_empty(),
            "the released target must converge immediately to its disk graph"
        );
    }

    /// If the oldest alias retargets, the old canonical root transfers to the
    /// next live alias in the same reconcile commit.
    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_symlink_retarget_hands_old_root_to_next_open_owner() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("first.R"), "first_disk <- 1\n").unwrap();
        fs::write(tmp.path().join("second.R"), "second_disk <- 1\n").unwrap();
        fs::write(tmp.path().join("a-extra.R"), "a_extra <- 1\n").unwrap();
        fs::write(tmp.path().join("b-extra.R"), "b_extra <- 1\n").unwrap();
        let link_a = tmp.path().join("link-a.R");
        let link_b = tmp.path().join("link-b.R");
        std::os::unix::fs::symlink("first.R", &link_a).unwrap();
        std::os::unix::fs::symlink("first.R", &link_b).unwrap();
        let (svc, _seed_uri) = open_in_workspace(&tmp, "a-extra.R", "r", "a_extra <- 1\n").await;
        let backend = svc.inner();
        let link_a_uri = Url::from_file_path(&link_a).unwrap();
        let link_b_uri = Url::from_file_path(&link_b).unwrap();
        let first_uri = Url::from_file_path(tmp.path().join("first.R")).unwrap();
        let second_uri = Url::from_file_path(tmp.path().join("second.R")).unwrap();
        let a_extra_uri = Url::from_file_path(tmp.path().join("a-extra.R")).unwrap();
        let b_extra_uri = Url::from_file_path(tmp.path().join("b-extra.R")).unwrap();
        open_doc(
            backend,
            &link_a_uri,
            "r",
            1,
            "source(\"a-extra.R\")\na <- 1\n",
        )
        .await;
        open_doc(
            backend,
            &link_b_uri,
            "r",
            1,
            "source(\"b-extra.R\")\nb <- 1\n",
        )
        .await;

        fs::remove_file(&link_a).unwrap();
        std::os::unix::fs::symlink("second.R", &link_a).unwrap();
        send_watched_change(backend, &link_a_uri).await;

        let state = backend.state.read().await;
        assert_eq!(
            state.open_document_uri_for_authoritative_uri(&first_uri),
            Some(link_b_uri)
        );
        assert_eq!(
            state.open_document_uri_for_authoritative_uri(&second_uri),
            Some(link_a_uri)
        );
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&first_uri)
                .iter()
                .any(|edge| edge.to == b_extra_uri)
        );
        assert!(
            state
                .cross_file_graph
                .get_dependencies(&second_uri)
                .iter()
                .any(|edge| edge.to == a_extra_uri)
        );
    }

    #[cfg(unix)]
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn watched_alias_reconcile_second_topology_change_stops_without_effects() {
        let tmp = TempDir::new().unwrap();
        for name in ["first.R", "second.R", "third.R"] {
            fs::write(tmp.path().join(name), format!("{name:?} <- 1\n")).unwrap();
        }
        let link = tmp.path().join("link.R");
        std::os::unix::fs::symlink("first.R", &link).unwrap();
        let (svc, _seed_uri) = open_in_workspace(&tmp, "first.R", "r", "first_live <- 1\n").await;
        let backend = svc.inner();
        let link_uri = Url::from_file_path(&link).unwrap();
        let first_uri = Url::from_file_path(tmp.path().join("first.R")).unwrap();
        let second_uri = Url::from_file_path(tmp.path().join("second.R")).unwrap();
        let third_uri = Url::from_file_path(tmp.path().join("third.R")).unwrap();
        open_doc(backend, &link_uri, "r", 1, "link_live <- 1\n").await;
        let initial_aliases = backend
            .state
            .read()
            .await
            .canonical_uris_for_open_document(&link_uri);

        fs::remove_file(&link).unwrap();
        std::os::unix::fs::symlink("second.R", &link).unwrap();
        let first_pause = backend
            .state
            .write()
            .await
            .alias_reconcile_pre_commit_test_pause
            .arm(link_uri.clone());
        let handler = send_watched_change(backend, &link_uri);
        tokio::pin!(handler);
        tokio::select! {
            _ = first_pause.wait_arrived() => {}
            _ = &mut handler => panic!("alias reconcile skipped first barrier"),
            _ = tokio::time::sleep(std::time::Duration::from_secs(5)) => {
                panic!("alias reconcile did not reach first barrier")
            }
        }
        fs::remove_file(&link).unwrap();
        std::os::unix::fs::symlink("third.R", &link).unwrap();
        let second_pause = backend
            .state
            .write()
            .await
            .alias_reconcile_pre_commit_test_pause
            .arm(link_uri.clone());
        first_pause.release();
        tokio::select! {
            _ = second_pause.wait_arrived() => {}
            _ = &mut handler => panic!("first stale alias reconcile committed"),
            _ = tokio::time::sleep(std::time::Duration::from_secs(5)) => {
                panic!("alias reconcile did not perform its single retry")
            }
        }
        fs::remove_file(&link).unwrap();
        std::os::unix::fs::symlink("first.R", &link).unwrap();
        second_pause.release();
        handler.await;

        let state = backend.state.read().await;
        assert_eq!(
            state.canonical_uris_for_open_document(&link_uri),
            initial_aliases
        );
        assert_eq!(
            state.open_document_uri_for_authoritative_uri(&first_uri),
            Some(first_uri.clone()),
            "exact canonical open owner remains authoritative"
        );
        assert_eq!(
            state.open_document_uri_for_authoritative_uri(&second_uri),
            None
        );
        assert_eq!(
            state.open_document_uri_for_authoritative_uri(&third_uri),
            None
        );
    }

