    /// Issue #343 Task 4: on-type-formatting indents inside an R chunk body.
    /// The indentation engine receives the masked analysis text, so a newline
    /// inside a function body produces a body-indent edit at document
    /// coordinates exactly as a plain-R file would.
    #[tokio::test]
    async fn on_type_formatting_indents_inside_rmd_chunk() {
        // Cursor lands on the blank line 3, inside the brace block opened on
        // line 2; the engine should indent it under the block.
        //   0  ```{r}
        //   1  prose-free chunk
        //   2  f <- function() {
        //   3  (cursor here, empty)
        //   4  }
        //   5  ```
        let content = "```{r}\nx <- 1\nf <- function() {\n\n}\n```\n";
        let (svc, uri, _tmp) = open_rmd(content).await;

        let edits = svc
            .inner()
            .on_type_formatting(on_type_params(&uri, 3, 0))
            .await
            .expect("on_type_formatting must not error");
        let edits = edits.expect("on_type_formatting must return edits inside a chunk body");
        assert!(
            !edits.is_empty() && edits.iter().any(|e| e.new_text.contains(' ')),
            "indentation edit must add leading spaces inside the chunk function body, got {:?}",
            edits
        );
    }

    /// The complement: a newline on a prose line must be inert. Without the
    /// prose guard the engine would treat the blank masked line as top-level R
    /// and apply R indentation rules to markdown.
    #[tokio::test]
    async fn on_type_formatting_inert_on_rmd_prose() {
        // Line 2 is prose; an Enter there must yield no edits.
        let content = "```{r}\nx <- 1\n```\n\nSome prose line.\n";
        let (svc, uri, _tmp) = open_rmd(content).await;

        let edits = svc
            .inner()
            .on_type_formatting(on_type_params(&uri, 4, 5))
            .await
            .expect("on_type_formatting must not error");
        assert!(
            edits.is_none() || edits.as_ref().is_some_and(|e| e.is_empty()),
            "on_type_formatting must be inert on a prose line, got {:?}",
            edits
        );
    }

    // ====================================================================
    // Issue #343 Task 5: outgoing-only chunk-aware cross-file metadata.
    //
    // These exercise the production did_open / publish / on-demand paths to
    // prove that for an open `.Rmd`, cross-file metadata feeding the
    // dependency graph, the open-document authority, and the async missing-file phase
    // is derived from the MASKED analysis text (chunk bodies only), never
    // from prose, while raw content remains available to non-analysis
    // consumers.
    // ====================================================================

    /// Open an arbitrary file (by path under a freshly-initialized workspace)
    /// through the real `did_open` path. Returns the live `LspService`, the
    /// document URI, and the backing `TempDir`. The `TempDir` must already
    /// contain the workspace fixtures; `path` is relative to it.
    async fn open_in_workspace(
        tmp: &TempDir,
        rel_path: &str,
        language_id: &str,
        content: &str,
    ) -> (tower_lsp::LspService<Backend>, Url) {
        use tower_lsp::lsp_types::{DidOpenTextDocumentParams, TextDocumentItem};

        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();

        let uri = Url::from_file_path(tmp.path().join(rel_path)).unwrap();
        backend
            .did_open(DidOpenTextDocumentParams {
                text_document: TextDocumentItem {
                    uri: uri.clone(),
                    language_id: language_id.into(),
                    version: 1,
                    text: content.into(),
                },
            })
            .await;
        (svc, uri)
    }

    /// Open `uri` on an already-initialized backend (the `did_open` half of
    /// `open_in_workspace`, for second and reopened documents).
    async fn open_doc(backend: &Backend, uri: &Url, language_id: &str, version: i32, text: &str) {
        use tower_lsp::lsp_types::{DidOpenTextDocumentParams, TextDocumentItem};
        backend
            .did_open(DidOpenTextDocumentParams {
                text_document: TextDocumentItem {
                    uri: uri.clone(),
                    language_id: language_id.into(),
                    version,
                    text: text.into(),
                },
            })
            .await;
    }

    /// Replace `uri`'s full buffer text through the real `did_change` path.
    async fn change_doc(backend: &Backend, uri: &Url, version: i32, text: &str) {
        use tower_lsp::lsp_types::{
            DidChangeTextDocumentParams, TextDocumentContentChangeEvent,
            VersionedTextDocumentIdentifier,
        };
        backend
            .did_change(DidChangeTextDocumentParams {
                text_document: VersionedTextDocumentIdentifier {
                    uri: uri.clone(),
                    version,
                },
                content_changes: vec![TextDocumentContentChangeEvent {
                    range: None,
                    range_length: None,
                    text: text.into(),
                }],
            })
            .await;
    }

    #[tokio::test]
    async fn did_change_applies_full_sync_then_utf16_ranges_to_rmd_through_open_edit_seam() {
        use tower_lsp::lsp_types::{
            DidChangeTextDocumentParams, Position, Range, TextDocumentContentChangeEvent,
            VersionedTextDocumentIdentifier,
        };

        let tmp = tempfile::TempDir::new().unwrap();
        let (svc, uri) = open_in_workspace(
            &tmp,
            "report.Rmd",
            "rmd",
            "old prose\n```{r}\nold <- 0\n```\n",
        )
        .await;
        let backend = svc.inner();
        backend
            .did_change(DidChangeTextDocumentParams {
                text_document: VersionedTextDocumentIdentifier {
                    uri: uri.clone(),
                    version: 2,
                },
                content_changes: vec![
                    TextDocumentContentChangeEvent {
                        range: None,
                        range_length: None,
                        text: "intro 🎉\n```{r}\nx <- 1\n```\n".into(),
                    },
                    TextDocumentContentChangeEvent {
                        range: Some(Range {
                            start: Position {
                                line: 0,
                                character: 8,
                            },
                            end: Position {
                                line: 0,
                                character: 8,
                            },
                        }),
                        range_length: None,
                        text: "!".into(),
                    },
                    TextDocumentContentChangeEvent {
                        range: Some(Range {
                            start: Position {
                                line: 2,
                                character: 0,
                            },
                            end: Position {
                                line: 2,
                                character: 1,
                            },
                        }),
                        range_length: None,
                        text: "中".into(),
                    },
                ],
            })
            .await;

        let state = backend.state.read().await;
        let document = state.documents.get(&uri).unwrap();
        assert_eq!(document.text(), "intro 🎉!\n```{r}\n中 <- 1\n```\n");
        assert!(document.analysis_text().contains("中 <- 1"));
        assert!(!document.analysis_text().contains("intro"));
    }

    #[test]
    fn open_edit_overflow_commits_local_facts_and_drops_foreign_edges() {
        let root = Url::parse("file:///workspace/").unwrap();
        let uri = Url::parse("file:///workspace/open.R").unwrap();
        let parent = Url::parse("file:///workspace/parent.R").unwrap();
        let child = Url::parse("file:///workspace/child.R").unwrap();
        let text =
            "# raven: sourced-by parent.R\nsource(\"child.R\")\nlibrary(stats)\nlocal_value <- 1\n";
        let mut state = WorldState::new();
        state.workspace_folders.push(root);
        state.open_document(uri.clone(), "before <- 1\n", Some(1));
        state.open_document(parent.clone(), "parent_value <- 1\n", Some(1));
        state.open_document(child.clone(), "child_value <- 1\n", Some(1));

        let prepared = state
            .prepare_document_changes(
                &uri,
                [tower_lsp::lsp_types::TextDocumentContentChangeEvent {
                    range: None,
                    range_length: None,
                    text: text.into(),
                }],
                2,
            )
            .unwrap();
        let prepared =
            state.force_open_edit_context_overflow_for_test(prepared, vec![parent.clone()]);
        let captured =
            capture_open_edit_fallback(&state, &uri, &prepared, state.get_enriched_metadata(&uri));
        let (metadata, plan) = derive_open_edit_fallback(captured);
        state
            .try_commit_analysis(PreparedAnalysisCommit::OpenEdit(Box::new(
                PreparedOpenEditAnalysis::new(prepared, Arc::new(metadata), plan),
            )))
            .unwrap();

        let record = state.documents.get_record(&uri).unwrap();
        assert_eq!(record.document().text(), text);
        assert_eq!(record.document().version, Some(2));
        assert_eq!(record.document().revision, 1);
        assert!(
            record
                .artifacts()
                .exported_interface
                .contains_key("local_value")
        );
        assert_eq!(record.metadata().sources.len(), 1);
        assert_eq!(record.metadata().sourced_by.len(), 1);
        assert!(
            record
                .metadata()
                .library_calls
                .iter()
                .any(|call| call.package == "stats")
        );
        assert!(
            record
                .document()
                .loaded_packages
                .iter()
                .any(|pkg| pkg == "stats")
        );
        let dependencies = state.cross_file_graph.get_dependencies(&uri);
        assert!(dependencies.iter().any(|edge| edge.to == child));
        assert!(dependencies.iter().all(|edge| !edge.non_lending));
        assert!(
            state
                .cross_file_graph
                .get_dependents(&uri)
                .iter()
                .all(|edge| edge.from != parent),
            "the foreign backward-parent edge must fail closed"
        );
    }

    #[test]
    fn detached_metadata_records_subject_and_alias_wd_attempts_even_when_absent() {
        let uri = Url::parse("file:///workspace/open.R").unwrap();
        let alias = Url::parse("file:///alias/open.R").unwrap();
        let subject_parent = Url::parse("file:///workspace/parent.R").unwrap();
        let alias_parent = Url::parse("file:///alias/parent.R").unwrap();
        let mut state = WorldState::new();
        state.open_document(
            uri.clone(),
            "# raven: sourced-by parent.R\nvalue <- 1\n",
            Some(1),
        );
        let generation = state.documents.get_record(&uri).unwrap().generation();
        let mut captured = state
            .capture_open_metadata_derivation(&uri, generation)
            .unwrap();
        captured.graph_roots = vec![uri, alias];

        let derived = derive_open_metadata_reenrichment(&captured);

        assert!(derived.context_uris.contains(&subject_parent));
        assert!(derived.context_uris.contains(&alias_parent));
    }

    #[tokio::test]
