    #[tokio::test]
    async fn did_open_commits_after_one_degraded_package_initialization_attempt() {
        let tmp = TempDir::new().unwrap();
        let subject = Url::from_file_path(tmp.path().join("subject.R")).unwrap();
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();
        let degraded_key = {
            let mut state = backend.state.write().await;
            state.workspace_scan_complete = true;
            state.cross_file_config.packages_enabled = true;
            state.package_library_ready = false;
            state.force_package_library_not_ready_for_test = true;
            PackageInitKey::capture(&state)
        };

        tokio::time::timeout(
            std::time::Duration::from_secs(5),
            open_doc(backend, &subject, "r", 1, "subject <- 1\n"),
        )
        .await
        .expect("supported degraded package initialization must not loop didOpen forever");

        let state = backend.state.read().await;
        assert!(!state.package_library_ready);
        assert_eq!(
            state
                .documents
                .get(&subject)
                .map(|document| document.text()),
            Some("subject <- 1\n".into())
        );
        drop(state);
        assert_eq!(
            backend
                .package_library_install_keys_for_test
                .lock()
                .unwrap()
                .as_slice(),
            std::slice::from_ref(&degraded_key),
            "a stable degraded key gets one bounded didOpen attempt; post-commit prefetch must not retry it"
        );
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn did_open_rejects_stale_package_build_and_retries_exact_fresh_key() {
        let tmp = TempDir::new().unwrap();
        let fresh_workspace = tmp.path().join("fresh-workspace");
        fs::create_dir(&fresh_workspace).unwrap();
        let subject = Url::from_file_path(tmp.path().join("subject.R")).unwrap();
        let pause_uri = Url::parse("raven-test://package-library-init").unwrap();
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "old".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();
        let install_key_baseline = backend
            .package_library_install_keys_for_test
            .lock()
            .unwrap()
            .len();
        let (first_pause, original_library, original_key) = {
            let mut state = backend.state.write().await;
            state.workspace_scan_complete = true;
            state.cross_file_config.packages_enabled = true;
            state.package_library_ready = false;
            state.force_package_library_not_ready_for_test = true;
            (
                state
                    .package_init_pre_commit_test_pause
                    .arm(pause_uri.clone()),
                state.package_library.clone(),
                PackageInitKey::capture(&state),
            )
        };

        let handler = open_doc(backend, &subject, "r", 1, "subject <- 1\n");
        tokio::pin!(handler);
        tokio::select! {
            _ = first_pause.wait_arrived() => {}
            _ = &mut handler => panic!("package initialization skipped first CAS barrier"),
            _ = tokio::time::sleep(std::time::Duration::from_secs(5)) => {
                panic!("package initialization did not reach first CAS barrier")
            }
        }
        let (second_pause, fresh_key) = {
            let mut state = backend.state.write().await;
            state.cross_file_config.packages_r_path = Some(fresh_workspace.join("different-R"));
            state.workspace_folders = vec![Url::from_file_path(&fresh_workspace).unwrap()];
            state.record_package_input_mutation();
            (
                state
                    .package_init_pre_commit_test_pause
                    .arm(pause_uri.clone()),
                PackageInitKey::capture(&state),
            )
        };
        assert_ne!(
            original_key, fresh_key,
            "the forced config/workspace mutation must produce a distinct retry key"
        );
        first_pause.release();
        tokio::select! {
            _ = second_pause.wait_arrived() => {}
            _ = &mut handler => panic!("stale package build was mislabeled current"),
            _ = tokio::time::sleep(std::time::Duration::from_secs(5)) => {
                panic!("didOpen did not retry package initialization for the fresh key")
            }
        }
        {
            let state = backend.state.read().await;
            assert!(
                Arc::ptr_eq(&state.package_library, &original_library),
                "the stale first build must not replace package-library state"
            );
            assert_eq!(
                backend
                    .package_library_install_keys_for_test
                    .lock()
                    .unwrap()
                    .len(),
                install_key_baseline,
                "the stale first build must not win a package-library CAS"
            );
            assert!(!state.documents.contains_key(&subject));
        }
        second_pause.release();
        handler.await;

        let state = backend.state.read().await;
        assert!(
            !Arc::ptr_eq(&state.package_library, &original_library),
            "the exact fresh-key build must replace the retained original library"
        );
        assert_eq!(
            PackageInitKey::capture(&state),
            fresh_key,
            "the committed library must still correspond to the exact fresh key"
        );
        assert!(!state.package_library_ready);
        assert!(state.documents.contains_key(&subject));
        drop(state);

        let install_keys = backend
            .package_library_install_keys_for_test
            .lock()
            .unwrap();
        let committed_after_baseline = &install_keys[install_key_baseline..];
        // Keep a strong original Arc above: a bare numeric address became
        // allocator-history-sensitive when degraded post-commit prefetch
        // retried the fresh key and reused the just-freed original address.
        // The central-CAS key log proves both halves directly: stale never
        // installs, and didOpen's one bounded fresh-key build is the sole win.
        assert_eq!(
            committed_after_baseline,
            std::slice::from_ref(&fresh_key),
            "exactly one fresh key and no stale key must win the library CAS"
        );
    }

    #[tokio::test]
    async fn did_open_awaits_inherited_package_prefetch_before_ticket_spawn() {
        let tmp = TempDir::new().unwrap();
        let library = tmp.path().join("library");
        let package = library.join("fakepkg");
        fs::create_dir_all(&package).unwrap();
        fs::write(
            package.join("DESCRIPTION"),
            "Package: fakepkg\nVersion: 1.0\n",
        )
        .unwrap();
        fs::write(package.join("NAMESPACE"), "export(fake_export)\n").unwrap();
        fs::write(tmp.path().join("parent.R"), "library(fakepkg)\n").unwrap();
        let subject = Url::from_file_path(tmp.path().join("subject.R")).unwrap();
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();
        let pause = {
            let mut state = backend.state.write().await;
            state.workspace_scan_complete = true;
            state.cross_file_config.packages_enabled = true;
            state.cross_file_config.on_demand_indexing_enabled = true;
            state.cross_file_config.packages_additional_library_paths = vec![library];
            state.package_library_ready = false;
            state.did_open_reservation_test_pause.arm(subject.clone())
        };
        let handler = open_doc(
            backend,
            &subject,
            "r",
            1,
            "source(\"parent.R\")\nfake_export()\n",
        );
        tokio::pin!(handler);
        tokio::select! {
            _ = pause.wait_arrived() => {}
            _ = &mut handler => panic!("didOpen skipped post-prefetch barrier"),
            _ = tokio::time::sleep(std::time::Duration::from_secs(10)) => {
                panic!("didOpen did not finish inherited package warming")
            }
        }
        let package_library = backend.state.read().await.package_library.clone();
        assert!(
            backend.state.read().await.package_library_ready,
            "real didOpen package convergence must install a ready library before prefetch"
        );
        assert!(
            package_library.is_cached("fakepkg").await,
            "inherited package must be cached before reservation barrier"
        );
        assert!(
            !backend
                .state
                .read()
                .await
                .cross_file_revalidation
                .has_pending_for_test(&subject),
            "no diagnostic ticket may spawn before inherited warming completes"
        );
        pause.release();
        handler.await;
    }

    #[tokio::test]
    async fn excluded_did_open_cap_one_reserves_dependent_not_direct_subject() {
        let tmp = TempDir::new().unwrap();
        let subject = Url::from_file_path(tmp.path().join("excluded.R")).unwrap();
        let dependent = Url::from_file_path(tmp.path().join("dependent.R")).unwrap();
        fs::write(tmp.path().join("excluded.R"), "disk_value <- 0\n").unwrap();
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();
        {
            let mut state = backend.state.write().await;
            state.workspace_scan_complete = true;
            state.cross_file_config.packages_enabled = false;
            state.cross_file_config.on_demand_indexing_enabled = false;
            state.cross_file_config.max_revalidations_per_trigger = 1;
            state.workspace_exclusions = crate::config_file::compile_workspace_exclusions(
                &serde_json::json!({ "workspace": { "exclude": ["excluded.R"] } }),
                vec![tmp.path().to_path_buf()],
            );
        }
        open_doc(
            backend,
            &dependent,
            "r",
            1,
            "source(\"excluded.R\")\nuse <- local_value\n",
        )
        .await;
        wait_for_revalidation_drain(backend, &[&dependent]).await;
        let pause = {
            let mut state = backend.state.write().await;
            let metadata =
                crate::cross_file::extract_metadata("source(\"excluded.R\")\nuse <- local_value\n");
            let workspace_root = state.workspace_folders.first().cloned();
            state.cross_file_graph.update_file(
                &dependent,
                &metadata,
                workspace_root.as_ref(),
                |_| Some("disk_value <- 0\n".into()),
            );
            assert!(
                state
                    .cross_file_graph
                    .get_dependencies(&dependent)
                    .iter()
                    .any(|edge| edge.to == subject),
                "fixture must retain the open dependent's pre-install edge"
            );
            state.did_open_reservation_test_pause.arm(subject.clone())
        };
        let handler = open_doc(backend, &subject, "r", 1, "local_value <- 1\n");
        tokio::pin!(handler);
        tokio::select! {
            _ = pause.wait_arrived() => {}
            _ = &mut handler => panic!("excluded didOpen skipped reservation barrier"),
            _ = tokio::time::sleep(std::time::Duration::from_secs(5)) => {
                panic!("excluded didOpen must reach the post-warm reservation barrier")
            }
        }
        {
            let state = backend.state.read().await;
            assert_eq!(
                state.did_open_reservation_snapshot_for_test,
                vec![(
                    dependent.clone(),
                    state
                        .diagnostics_gate
                        .force_republish_count_for_test(&dependent)
                )]
            );
            assert_eq!(
                state
                    .diagnostics_gate
                    .force_republish_count_for_test(&subject),
                0
            );
            assert_eq!(
                state
                    .diagnostics_gate
                    .force_republish_count_for_test(&dependent),
                1
            );
        }
        pause.release();
        handler.await;
    }

    #[tokio::test]
    async fn did_open_rmd_language_override_masks_fake_prose_for_file_and_untitled() {
        let tmp = TempDir::new().unwrap();
        let file_uri = Url::from_file_path(tmp.path().join("report.R")).unwrap();
        let untitled_uri = Url::parse("untitled:Untitled-650").unwrap();
        let text = concat!(
            "# prose source(\"fake-prose.R\") and fake_prose <- 1\n",
            "\n",
            "```{r}\n",
            "source(\"real-chunk.R\")\n",
            "real_chunk <- 1\n",
            "```\n",
        );
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();
        {
            let mut state = backend.state.write().await;
            state.workspace_scan_complete = true;
            state.cross_file_config.packages_enabled = false;
            state.cross_file_config.on_demand_indexing_enabled = false;
        }

        open_doc(backend, &file_uri, "rmd", 1, text).await;
        open_doc(backend, &untitled_uri, "rmd", 1, text).await;

        let state = backend.state.read().await;
        for uri in [&file_uri, &untitled_uri] {
            let record = state.documents.get_record(uri).unwrap();
            assert!(record.document().is_rmd_document());
            assert_eq!(
                record
                    .metadata()
                    .sources
                    .iter()
                    .map(|source| source.path.as_str())
                    .collect::<Vec<_>>(),
                vec!["real-chunk.R"]
            );
            assert!(
                record
                    .artifacts()
                    .exported_interface
                    .contains_key("real_chunk")
            );
            assert!(
                !record
                    .artifacts()
                    .exported_interface
                    .contains_key("fake_prose")
            );
        }
    }

    #[derive(Debug, PartialEq, Eq)]
    struct CloseCentralSnapshot {
        document: Option<(
            String,
            Option<i32>,
            u64,
            Option<crate::cross_file::revalidation::DiagnosticsEpoch>,
        )>,
        aliases: Vec<Url>,
        activity: (Option<Url>, Vec<Url>, Vec<Url>),
        graph: String,
        index: (u64, Option<String>),
        raw: (u64, Option<String>),
        package: (u64, String, crate::package_state::PackageState),
        watched: HashMap<Url, u64>,
        chunk_overrides: HashMap<Url, crate::chunks::ChunkKind>,
        pins: std::collections::HashSet<Url>,
        reservations: usize,
        force: u32,
    }

    fn close_central_snapshot(state: &WorldState, uri: &Url) -> CloseCentralSnapshot {
        CloseCentralSnapshot {
            document: state.documents.get_record(uri).map(|record| {
                (
                    record.document().text(),
                    record.document().version,
                    record.document().revision,
                    record.provenance().lifecycle_epoch,
                )
            }),
            aliases: state.canonical_uris_for_open_document(uri),
            activity: (
                state.cross_file_activity.active_uri.clone(),
                state.cross_file_activity.visible_uris.clone(),
                state.cross_file_activity.recent_uris.clone(),
            ),
            graph: format!("{:?}", state.cross_file_graph),
            index: (
                state.workspace_index.version(),
                state
                    .workspace_index
                    .get(uri)
                    .map(|entry| entry.contents.to_string()),
            ),
            raw: (
                state.cross_file_file_cache.content_generation(),
                state.cross_file_file_cache.get(uri),
            ),
            package: (
                state.package_input_generation(),
                format!("{:?}", state.package_inputs),
                state.package_state.clone(),
            ),
            watched: state.watched_file_resync_generations.clone(),
            chunk_overrides: state.editor_chunk_kind_overrides.clone(),
            pins: state.workspace_index.pinned_uris_for_test(),
            reservations: state.analysis_revalidation_reservation_count,
            force: state.diagnostics_gate.force_republish_count_for_test(uri),
        }
    }

    #[tokio::test]
    async fn did_close_target_edit_is_terminal_and_never_rebases() {
        let tmp = TempDir::new().unwrap();
        let (svc, uri) = open_in_workspace(&tmp, "close-edit-owner.R", "r", "before <- 1\n").await;
        let backend = svc.inner();
        let pause = backend
            .state
            .write()
            .await
            .did_close_pre_commit_test_pause
            .arm(uri.clone());
        let close = close_doc(backend, &uri);
        tokio::pin!(close);
        tokio::select! {
            _ = pause.wait_arrived() => {}
            _ = &mut close => panic!("close skipped its pre-commit barrier"),
            _ = tokio::time::sleep(std::time::Duration::from_secs(5)) => {
                panic!("close did not reach its pre-commit barrier")
            }
        }
        change_doc(backend, &uri, 2, "edited <- 2\n").await;
        let expected = {
            let state = backend.state.read().await;
            close_central_snapshot(&state, &uri)
        };
        pause.release();
        close.await;
        let state = backend.state.read().await;
        assert_eq!(close_central_snapshot(&state, &uri), expected);
        assert_eq!(
            state
                .open_close_intent_for_test(&uri)
                .map(|intent| intent.0),
            Some("cancelled")
        );
        let record = state.documents.get_record(&uri).expect("edit remains open");
        assert_eq!(record.document().text(), "edited <- 2\n");
        assert_eq!(record.document().version, Some(2));
    }

