    #[cfg(unix)]
    #[tokio::test]
    async fn did_close_retries_non_subject_watched_generation_and_leaves_unrelated_untouched() {
        let tmp = TempDir::new().unwrap();
        let real = tmp.path().join("real");
        fs::create_dir(&real).unwrap();
        fs::write(real.join("owner.R"), "disk <- 1\n").unwrap();
        std::os::unix::fs::symlink(&real, tmp.path().join("link")).unwrap();
        let alias_uri = Url::from_file_path(tmp.path().join("link/owner.R")).unwrap();
        let canonical_uri = Url::from_file_path(real.join("owner.R")).unwrap();
        let unrelated_uri = Url::from_file_path(tmp.path().join("unrelated.R")).unwrap();
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();
        backend
            .initialize(InitializeParams {
                workspace_folders: Some(vec![WorkspaceFolder {
                    uri: Url::from_file_path(tmp.path()).unwrap(),
                    name: "t".into(),
                }]),
                ..Default::default()
            })
            .await
            .unwrap();
        open_doc(backend, &alias_uri, "r", 1, "live <- 1\n").await;
        let first_pause = {
            let mut state = backend.state.write().await;
            state
                .watched_file_resync_generations
                .insert(canonical_uri.clone(), 10);
            state
                .watched_file_resync_generations
                .insert(unrelated_uri.clone(), 99);
            state.did_close_pre_commit_test_pause.arm(alias_uri.clone())
        };
        let close = close_doc(backend, &alias_uri);
        tokio::pin!(close);
        tokio::select! {
            _ = first_pause.wait_arrived() => {}
            _ = &mut close => panic!("close skipped first watched-generation barrier"),
            _ = tokio::time::sleep(std::time::Duration::from_secs(5)) => {
                panic!("close did not reach first watched-generation barrier")
            }
        }
        let second_pause = {
            let mut state = backend.state.write().await;
            state
                .watched_file_resync_generations
                .insert(canonical_uri.clone(), 11);
            state.did_close_pre_commit_test_pause.arm(alias_uri.clone())
        };
        first_pause.release();
        tokio::select! {
            _ = second_pause.wait_arrived() => {}
            _ = &mut close => panic!("stale non-subject watched basis committed"),
            _ = tokio::time::sleep(std::time::Duration::from_secs(5)) => {
                panic!("close did not perform its one fresh watched-basis retry")
            }
        }
        second_pause.release();
        close.await;
        let state = backend.state.read().await;
        assert!(!state.documents.contains_key(&alias_uri));
        assert_ne!(
            state.watched_file_resync_generations.get(&canonical_uri),
            Some(&11)
        );
        assert_eq!(
            state.watched_file_resync_generations.get(&unrelated_uri),
            Some(&99)
        );
    }

    /// Close `uri` through the real `did_close` path.
    async fn close_doc(backend: &Backend, uri: &Url) {
        use tower_lsp::lsp_types::{DidCloseTextDocumentParams, TextDocumentIdentifier};
        backend
            .did_close(DidCloseTextDocumentParams {
                text_document: TextDocumentIdentifier { uri: uri.clone() },
            })
            .await;
    }

    /// Send a single watched CHANGED event through the real watched-files path.
    async fn send_watched_change(backend: &Backend, uri: &Url) {
        use tower_lsp::lsp_types::{DidChangeWatchedFilesParams, FileChangeType, FileEvent};
        backend
            .did_change_watched_files(DidChangeWatchedFilesParams {
                changes: vec![FileEvent {
                    uri: uri.clone(),
                    typ: FileChangeType::CHANGED,
                }],
            })
            .await;
    }

    /// Seed package-mode R-file input for a closed disk file so watched resync
    /// tests can assert update/removal of the incremental package input cache.
    async fn seed_package_r_file_input(
        backend: &Backend,
        root: &std::path::Path,
        rel_path: &str,
        text: &str,
    ) {
        let path = root.join(rel_path);
        let kind = crate::package_state::is_r_source_path(&path, root)
            .expect("test helper seeds only package R source paths");
        let text: std::sync::Arc<str> = text.into();
        let content_digest = crate::package_state::ContentDigest::of(&text);
        let mut state = backend.state.write().await;
        state.package_inputs.workspace_root = Some(root.to_path_buf());
        state.package_inputs.r_files.insert(
            path,
            crate::package_state::RFileInput {
                kind,
                text,
                content_digest,
            },
        );
    }

    /// Seed package-mode DESCRIPTION input and derived state for manifest
    /// watched-resync tests.
    async fn seed_package_description_input(backend: &Backend, root: &std::path::Path, text: &str) {
        let mut state = backend.state.write().await;
        state.package_inputs.workspace_root = Some(root.to_path_buf());
        state.package_inputs.description = Some(crate::package_state::DescriptionInput {
            text: std::sync::Arc::from(text),
        });
        state.apply_package_event(&crate::package_state::PackageInputDelta::Initial);
    }

    /// Poll `check` against fresh `WorldState` read snapshots until it
    /// returns `true` or `timeout_ms` elapses. Returns whether the condition
    /// was met. For tests that assert on the outcome of fire-and-forget
    /// background work (the watched-files async disk-read pass, the
    /// `did_close` disk resync), which has no join handle to await.
    async fn wait_for_state<F>(backend: &Backend, timeout_ms: u64, mut check: F) -> bool
    where
        F: FnMut(&WorldState) -> bool,
    {
        let deadline = std::time::Instant::now() + std::time::Duration::from_millis(timeout_ms);
        loop {
            {
                let state = backend.state.read().await;
                if check(&state) {
                    return true;
                }
            }
            if std::time::Instant::now() >= deadline {
                return false;
            }
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
    }

    fn snapshot_diagnostics(
        state: &WorldState,
        uri: &Url,
    ) -> Vec<tower_lsp::lsp_types::Diagnostic> {
        let snapshot =
            crate::handlers::DiagnosticsSnapshot::build(state, uri).expect("snapshot must build");
        if snapshot.file_type == crate::file_type::FileType::R {
            crate::handlers::diagnostics_from_snapshot(
                &snapshot,
                uri,
                &crate::handlers::DiagCancelToken::never(),
            )
            .unwrap_or_default()
        } else {
            Vec::new()
        }
    }

    fn has_dependency_edge(state: &WorldState, from: &Url, to: &Url) -> bool {
        state
            .cross_file_graph
            .get_dependencies(from)
            .iter()
            .any(|edge| &edge.to == to)
    }

    fn has_helper_fn_undefined(state: &WorldState, uri: &Url) -> bool {
        snapshot_diagnostics(state, uri)
            .iter()
            .any(|diagnostic| diagnostic.message.contains("helper_fn is not defined"))
    }

    fn assert_project_excluded_live_source_non_lending(
        state: &WorldState,
        excluded_uri: &Url,
        helper_uri: &Url,
        helper_symbol: &str,
    ) {
        assert!(
            state
                .cross_file_graph
                .get_dependencies(excluded_uri)
                .iter()
                .any(|edge| edge.to == *helper_uri && edge.non_lending),
            "excluded buffer should keep a non-lending forward edge for its own diagnostics"
        );
        assert!(
            state
                .cross_file_graph
                .get_dependents(helper_uri)
                .iter()
                .any(|edge| edge.from == *excluded_uri && edge.non_lending),
            "excluded buffer reverse edge should be retained for revalidation but non-lending"
        );
        assert!(
            !state
                .cross_file_graph
                .get_dependents(helper_uri)
                .iter()
                .any(|edge| edge.from == *excluded_uri && !edge.non_lending),
            "excluded buffer must not be a lending parent of the non-excluded helper"
        );
        assert!(
            !state.workspace_index.contains(excluded_uri)
                && !state.workspace_index.contains(excluded_uri),
            "excluded open buffer must stay out of workspace indexes"
        );
        let undefined_message = format!("{helper_symbol} is not defined");
        assert!(
            !snapshot_diagnostics(state, excluded_uri)
                .iter()
                .any(|diagnostic| diagnostic.message.contains(&undefined_message)),
            "excluded buffer's own source() target should resolve; diagnostics: {:?}",
            diagnostic_signature(state, excluded_uri)
        );
    }

    fn diagnostic_signature(state: &WorldState, uri: &Url) -> Vec<(u32, String)> {
        snapshot_diagnostics(state, uri)
            .into_iter()
            .map(|diagnostic| (diagnostic.range.start.line, diagnostic.message))
            .collect()
    }

    /// Flag #1: an open Rmd whose chunk `source()`s an existing helper must
    /// produce an outgoing dependency-graph edge, and a symbol defined in the
    /// helper used in a later chunk must NOT be flagged undefined.
    #[tokio::test]
    async fn rmd_chunk_source_produces_outgoing_edge_and_resolves_symbol() {
        let tmp = TempDir::new().unwrap();
        fs::write(tmp.path().join("helpers.R"), "helper_fn <- function() 1\n").unwrap();
        // Prose mentions `source(\"prose_decoy.R\")` which must be ignored; the
        // real source() lives in an R chunk. A later chunk uses helper_fn().
        let rmd = concat!(
            "# Report\n",
            "\n",
            "Prose calls source(\"prose_decoy.R\") but that is not R.\n",
            "\n",
            "```{r}\n",
            "source(\"helpers.R\")\n",
            "```\n",
            "\n",
            "More prose.\n",
            "\n",
            "```{r}\n",
            "y <- helper_fn()\n",
            "```\n",
        );
        fs::write(tmp.path().join("analysis.Rmd"), rmd).unwrap();

        let (svc, uri) = open_in_workspace(&tmp, "analysis.Rmd", "rmd", rmd).await;
        let backend = svc.inner();
        let state = backend.state.read().await;

        // Outgoing edge analysis.Rmd -> helpers.R exists, and the decoy does not.
        let helpers_uri = Url::from_file_path(tmp.path().join("helpers.R")).unwrap();
        let decoy_uri = Url::from_file_path(tmp.path().join("prose_decoy.R")).unwrap();
        let deps = state.cross_file_graph.get_dependencies(&uri);
        let targets: Vec<&Url> = deps.iter().map(|e| &e.to).collect();
        assert!(
            targets.contains(&&helpers_uri),
            "chunk source() must add an outgoing edge to helpers.R; edges: {:?}",
            targets
        );
        assert!(
            !targets.contains(&&decoy_uri),
            "prose source() must NOT add an edge; edges: {:?}",
            targets
        );

        // helper_fn used in a later chunk must resolve (no undefined-var diag).
        let diags = snapshot_diagnostics(&state, &uri);
        assert!(
            !diags
                .iter()
                .any(|d| d.message.contains("helper_fn is not defined")),
            "helper_fn from the sourced helper must resolve; diagnostics: {:?}",
            diags
                .iter()
                .map(|d| (d.range.start.line, d.message.clone()))
                .collect::<Vec<_>>()
        );
    }

    /// Flag #3: a chunk `source("nonexistent.R")` must yield a missing-file
    /// diagnostic through the ASYNC publish path. The async path strips the
    /// sync missing-file diagnostics and re-adds them from a separately-built
    /// `directive_meta`. Pre-fix, `publish_diagnostics_inner` Phase 1 built
    /// that meta from `parse_directives(doc.text())` — RAW and directives-only,
    /// so it carried NO AST `source()` calls — and the chunk's missing-file
    /// diagnostic was silently lost. The fix sources `directive_meta` from
    /// `snapshot.directive_meta` (full `extract_metadata`, masked for Rmd).
    #[tokio::test]
    async fn rmd_chunk_missing_source_flagged_through_async_publish_path() {
        let tmp = TempDir::new().unwrap();
        let rmd = concat!(
            "# Report\n",
            "\n",
            "```{r}\n",
            "source(\"nonexistent.R\")\n",
            "```\n",
        );
        fs::write(tmp.path().join("analysis.Rmd"), rmd).unwrap();
        let (svc, uri) = open_in_workspace(&tmp, "analysis.Rmd", "rmd", rmd).await;
        let backend = svc.inner();

        // Reproduce publish_diagnostics_inner Phase 1-3 exactly (the production
        // async path), then assert the missing-file diagnostic survives at the
        // chunk's document line (line 3, 0-based).
        let (snapshot, directive_meta, raw_text, workspace_folder, missing_file_severity) = {
            let state = backend.state.read().await;
            let snapshot = crate::handlers::DiagnosticsSnapshot::build(&state, &uri);
            // Production Phase 1 sources directive_meta from the snapshot.
            let directive_meta = snapshot
                .as_ref()
                .map(|s| s.directive_meta.clone())
                .unwrap_or_default();
            let raw_text = state.get_document(&uri).map(|d| d.text()).unwrap();
            let wf = state.workspace_folders.first().cloned();
            let sev = state.cross_file_config.missing_file_severity;
            (snapshot, directive_meta, raw_text, wf, sev)
        };
        let snapshot = snapshot.expect("snapshot must build for Rmd");

        // The production directive_meta carries the chunk's AST source() call...
        assert!(
            directive_meta
                .sources
                .iter()
                .any(|s| s.path == "nonexistent.R"),
            "snapshot.directive_meta (the production async-phase source) must carry the chunk source() call"
        );
        // ...whereas the PRE-FIX source (raw `parse_directives`) does not — this
        // is exactly why the old code lost the diagnostic. Guarding it pins the
        // fix at the seam: a regression to `parse_directives(doc.text())` would
        // feed `diagnostics_async_standalone` a meta with no AST source() call.
        let prefix_meta = crate::cross_file::directive::parse_directives(&raw_text);
        assert!(
            !prefix_meta
                .sources
                .iter()
                .any(|s| s.path == "nonexistent.R"),
            "the pre-fix raw parse_directives must NOT carry the chunk source() — it is directives-only and prose-blind"
        );

        let sync_diagnostics = crate::handlers::diagnostics_from_snapshot(
            &snapshot,
            &uri,
            &crate::handlers::DiagCancelToken::never(),
        )
        .unwrap_or_default();
        let diagnostics = crate::handlers::diagnostics_async_standalone(
            &uri,
            sync_diagnostics,
            &directive_meta,
            workspace_folder.as_ref(),
            missing_file_severity,
            crate::cross_file::CaseMismatchSeverity::Auto,
        )
        .await;

        assert!(
            diagnostics.iter().any(|d| {
                (d.message.starts_with("File not found:")
                    || d.message.starts_with("Cannot resolve path:"))
                    && d.range.start.line == 3
            }),
            "missing-file diagnostic for the chunk source() must survive the async path on line 3; got {:?}",
            diagnostics
                .iter()
                .map(|d| (d.range.start.line, d.message.clone()))
                .collect::<Vec<_>>()
        );
    }

    /// A `# @lsp-cd` directive in Rmd PROSE must be ignored (prose is masked
    /// away), while the same directive inside an R chunk is honored. Asserted
    /// cheaply at the metadata-extraction seam via `extract_metadata_for_path`,
    /// the shared helper every Rmd extraction site routes through.
    #[test]
    fn rmd_lsp_cd_directive_honored_in_chunk_ignored_in_prose() {
        // Prose `# @lsp-cd` — masked away, so no working_directory.
        let prose_cd = "# @lsp-cd /tmp/prose\n\n```{r}\nx <- 1\n```\n";
        let meta = crate::cross_file::extract_metadata_for_path("a.Rmd", prose_cd);
        assert!(
            meta.working_directory.is_none(),
            "a @lsp-cd in prose must not set working_directory; got {:?}",
            meta.working_directory
        );

        // Chunk `# @lsp-cd` — a real directive inside R chunk body.
        let chunk_cd = "# heading\n\n```{r}\n# @lsp-cd /tmp/chunk\nx <- 1\n```\n";
        let meta = crate::cross_file::extract_metadata_for_path("a.Rmd", chunk_cd);
        assert_eq!(
            meta.working_directory.as_deref(),
            Some("/tmp/chunk"),
            "a @lsp-cd inside a chunk must set working_directory"
        );
    }

    /// Flag #2: after did_open of an Rmd, the open record exposes
    /// chunk-defined symbols via `get_artifacts` (not prose garbage), while
    /// `get_content` still returns the verbatim RAW text.
    #[tokio::test]
    async fn rmd_open_record_artifacts_masked_content_raw() {
        let tmp = TempDir::new().unwrap();
        let rmd = concat!(
            "# Heading is prose, not a symbol\n",
            "\n",
            "Some prose with words like analyze and report.\n",
            "\n",
            "```{r}\n",
            "chunk_symbol <- function() 1\n",
            "```\n",
        );
        fs::write(tmp.path().join("analysis.Rmd"), rmd).unwrap();
        let (svc, uri) = open_in_workspace(&tmp, "analysis.Rmd", "rmd", rmd).await;
        let backend = svc.inner();
        let state = backend.state.read().await;

        use crate::content_provider::ContentProvider;
        let cp = state.content_provider();
        // RAW content is preserved verbatim (prose included).
        let content = cp.get_content(&uri).expect("content available");
        assert_eq!(content, rmd, "get_content must return RAW Rmd text");
        assert!(
            content.contains("Heading is prose"),
            "raw content must still contain prose"
        );

        // Artifacts expose the chunk-defined symbol, derived from masked text.
        let artifacts = cp.get_artifacts(&uri).expect("artifacts available");
        let names: Vec<String> = artifacts
            .exported_interface
            .keys()
            .map(|k| k.to_string())
            .collect();
        assert!(
            names.iter().any(|n| n == "chunk_symbol"),
            "open-record artifacts must include the chunk-defined symbol; got {:?}",
            names
        );

        // Open-record metadata must be masked-derived (no prose noise).
        let meta = cp.get_metadata(&uri).expect("metadata available");
        assert!(
            meta.sources.is_empty(),
            "no source() in chunks, so metadata.sources must be empty (prose ignored); got {:?}",
            meta.sources
        );
    }

    /// Flag #2 / Document invariant: the open record's `tree` must be
    /// parsed from the masked analysis text. Pairing the tree with the raw
    /// content would mis-slice; here we assert the tree + analysis_text pair
    /// is self-consistent (the tree's root spans the masked text length).
    #[tokio::test]
    async fn rmd_open_record_tree_paired_with_masked_text() {
        let tmp = TempDir::new().unwrap();
        let rmd = "# prose\n\n```{r}\nz <- 1\n```\n";
        fs::write(tmp.path().join("analysis.Rmd"), rmd).unwrap();
        let (svc, uri) = open_in_workspace(&tmp, "analysis.Rmd", "rmd", rmd).await;
        let backend = svc.inner();
        let state = backend.state.read().await;

        let document = state.documents.get(&uri).expect("document in store");
        let analysis = document.analysis_text();
        let masked = crate::chunks::mask_to_r(rmd);
        assert_eq!(analysis, masked, "Document analysis_text must be masked");
        let tree = document.tree.as_ref().expect("tree parsed");
        assert_eq!(
            tree.root_node().end_byte(),
            analysis.len(),
            "tree must be parsed from the masked analysis text"
        );
    }

    /// Flag #4: opening a `.R` helper that declares `# @lsp-sourced-by
    /// analysis.Rmd` triggers on-demand indexing of the (closed) Rmd from disk.
    /// That extraction must be MASKED so `helper_fn` (defined in a chunk) is in
    /// the helper's inherited scope and is not flagged undefined. The Rmd's
    /// indexed content stays RAW while its indexed metadata reflects only chunk
    /// content.
    #[tokio::test]
    async fn r_file_sourced_by_rmd_resolves_chunk_symbol_via_masked_on_demand() {
        let tmp = TempDir::new().unwrap();
        let rmd = concat!(
            "# Analysis\n",
            "\n",
            "Prose source(\"prose_decoy.R\") here.\n",
            "\n",
            "```{r}\n",
            "library(tools)\n",
            "helper_fn <- function() 1\n",
            "```\n",
        );
        fs::write(tmp.path().join("analysis.Rmd"), rmd).unwrap();
        let helper = concat!("# @lsp-sourced-by analysis.Rmd\n", "x <- helper_fn()\n",);
        fs::write(tmp.path().join("helpers.R"), helper).unwrap();

        let (svc, helper_uri) = open_in_workspace(&tmp, "helpers.R", "r", helper).await;
        let backend = svc.inner();
        let state = backend.state.read().await;

        // The Rmd was indexed on demand. Its indexed metadata reflects ONLY
        // chunk content: library(tools) is detected, the prose decoy source()
        // is NOT.
        let rmd_uri = Url::from_file_path(tmp.path().join("analysis.Rmd")).unwrap();
        let rmd_meta = state
            .get_enriched_metadata(&rmd_uri)
            .expect("Rmd indexed metadata available");
        assert!(
            rmd_meta
                .library_calls
                .iter()
                .any(|lc| lc.package == "tools"),
            "masked on-demand extraction must find library(tools) from the chunk; got {:?}",
            rmd_meta.library_calls
        );
        assert!(
            rmd_meta.sources.is_empty(),
            "prose source() decoy must not appear in indexed Rmd metadata; got {:?}",
            rmd_meta.sources
        );

        // The indexed RAW content (file cache) still contains prose.
        let cached = state
            .cross_file_file_cache
            .get(&rmd_uri)
            .expect("Rmd content cached");
        assert!(
            cached.contains("Prose source"),
            "cross_file_file_cache must hold RAW Rmd content (with prose)"
        );

        // helper_fn (chunk-defined in the parent Rmd) resolves in helpers.R.
        let diags = snapshot_diagnostics(&state, &helper_uri);
        assert!(
            !diags
                .iter()
                .any(|d| d.message.contains("helper_fn is not defined")),
            "helper_fn from the parent Rmd chunk must resolve in helpers.R; diagnostics: {:?}",
            diags
                .iter()
                .map(|d| (d.range.start.line, d.message.clone()))
                .collect::<Vec<_>>()
        );
    }

    #[tokio::test]
    async fn on_demand_failed_read_aborts_claim_for_retry() {
        let tmp = TempDir::new().unwrap();
        let path = tmp.path().join("retry.R");
        let uri = Url::from_file_path(&path).unwrap();
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();

        assert!(backend.index_file_on_demand(&uri).await.is_none());
        assert_eq!(
            backend
                .state
                .read()
                .await
                .workspace_index
                .enrichment_status(&uri),
            None,
            "a failed disk read must abort, not strand Pending"
        );

        fs::write(&path, "retry_value <- 1\n").unwrap();
        assert!(backend.index_file_on_demand(&uri).await.is_some());
        assert!(backend.state.read().await.workspace_index.is_complete(&uri));
    }

    #[tokio::test]
    async fn concurrent_on_demand_indexing_deduplicates_pending_work() {
        let tmp = TempDir::new().unwrap();
        let path = tmp.path().join("large.R");
        let mut content = " ".repeat(4 * 1024 * 1024);
        content.push_str("\nlarge_value <- 1\n");
        fs::write(&path, content).unwrap();
        let uri = Url::from_file_path(&path).unwrap();
        let (svc, _socket) = tower_lsp::LspService::new(Backend::new);
        let backend = svc.inner();

        let (first, second) = tokio::join!(
            backend.index_file_on_demand(&uri),
            backend.index_file_on_demand(&uri)
        );
        assert_eq!(
            usize::from(first.is_some()) + usize::from(second.is_some()),
            1,
            "only the worker owning the Pending generation may parse and commit"
        );
        assert!(backend.state.read().await.workspace_index.is_complete(&uri));
    }

    fn complete_refresh_test_record(
        content: &str,
    ) -> (
        crate::workspace_index::IndexEntry,
        crate::cross_file::file_cache::FileSnapshot,
        String,
    ) {
        let content = content.to_string();
        let snapshot = crate::cross_file::file_cache::FileSnapshot {
            mtime: std::time::SystemTime::UNIX_EPOCH,
            size: content.len() as u64,
            content_hash: None,
        };
        (
            crate::workspace_index::IndexEntry {
                contents: ropey::Rope::from_str(&content),
                tree: None,
                loaded_packages: Vec::new(),
                data_packages: Vec::new(),
                snapshot: snapshot.clone(),
                metadata: Arc::new(crate::cross_file::CrossFileMetadata::default()),
                artifacts: Arc::new(crate::cross_file::scope::ScopeArtifacts::default()),
                indexed_at_version: 0,
            },
            snapshot,
            content,
        )
    }

    fn analyzed_test_record(
        content: &str,
    ) -> (
        crate::workspace_index::IndexEntry,
        crate::cross_file::file_cache::FileSnapshot,
        String,
    ) {
        let (mut entry, snapshot, content) = complete_refresh_test_record(content);
        entry.metadata = Arc::new(crate::cross_file::extract_metadata(&content));
        (entry, snapshot, content)
    }

    fn observed_test_upsert(
        state: &WorldState,
        uri: &Url,
        text: &str,
        contexts: Vec<Url>,
    ) -> crate::state::PreparedClosedMutation {
        let basis = state
            .attach_analysis_context_authorities(
                state.capture_closed_removal_analysis_basis(uri),
                contexts,
            )
            .expect("test context fits the traversal budget");
        let (entry, snapshot, content) = analyzed_test_record(text);
        let metadata = entry.metadata.clone();
        crate::state::PreparedClosedMutation::Upsert(Box::new(
            crate::state::PreparedClosedAnalysis::new(
                basis,
                uri.clone(),
                entry,
                snapshot,
                content,
                metadata,
                state.workspace_folders.first().cloned(),
                HashMap::new(),
                Vec::new(),
                Vec::new(),
            ),
        ))
    }

    fn complete_refresh_token(
        state: &WorldState,
        uri: &Url,
    ) -> crate::workspace_index::CompleteRefreshToken {
        match state.workspace_index.claim_enrichment(
            uri.clone(),
            crate::workspace_index::ClosedProvenance::Dynamic,
        ) {
            crate::workspace_index::ClaimEnrichment::AlreadyComplete(token) => token,
            other => panic!("expected Complete refresh token, got {other:?}"),
        }
    }

    fn try_commit_test_closed_analysis(
        state: &mut WorldState,
        basis: crate::state::AnalysisBasis,
        uri: &Url,
        entry: crate::workspace_index::IndexEntry,
        snapshot: crate::cross_file::file_cache::FileSnapshot,
        content: String,
    ) -> std::result::Result<
        crate::state::AnalysisCommitEffects,
        crate::state::AnalysisCommitRejected,
    > {
        let graph_metadata = entry.metadata.clone();
        let prepared = crate::state::PreparedClosedAnalysis::new(
            basis,
            uri.clone(),
            entry,
            snapshot,
            content,
            graph_metadata,
            None,
            HashMap::new(),
            Vec::new(),
            Vec::new(),
        );
        state.try_commit_analysis(crate::state::PreparedAnalysisCommit::Upsert(Box::new(
            prepared,
        )))
    }

    fn test_open_parent(
        state: &mut WorldState,
        parent: &Url,
        child: &Url,
    ) -> Arc<crate::cross_file::CrossFileMetadata> {
        let child_name = std::path::Path::new(child.path())
            .file_name()
            .unwrap()
            .to_string_lossy();
        state.open_document(
            parent.clone(),
            &format!("source(\"{child_name}\")\n"),
            Some(1),
        );
        state
            .documents
            .get_record(parent)
            .expect("open parent record")
            .metadata()
            .clone()
    }

    fn commit_test_closed_removal(
        state: &mut WorldState,
        basis: crate::state::AnalysisBasis,
        uri: &Url,
    ) -> std::result::Result<
        crate::state::AnalysisCommitEffects,
        crate::state::AnalysisCommitRejected,
    > {
        state.try_commit_analysis(crate::state::PreparedAnalysisCommit::Remove {
            basis: Box::new(basis),
            uri: uri.clone(),
        })
    }

    #[test]
    fn on_demand_commit_preserves_existing_fanout_ownership() {
        let mut state = WorldState::new();
        let uri = Url::parse("file:///workspace/on-demand.R").unwrap();
        let owner = Url::parse("file:///workspace/owner.R").unwrap();
        state.diagnostics_gate.mark_force_republish(&owner);
        let claim = match state.workspace_index.claim_enrichment(
            uri.clone(),
            crate::workspace_index::ClosedProvenance::Dynamic,
        ) {
            crate::workspace_index::ClaimEnrichment::Claimed(claim) => claim,
            other => panic!("expected Pending claim, got {other:?}"),
        };
        let basis = state.capture_closed_pending_analysis_basis(claim);
        let (entry, snapshot, content) = complete_refresh_test_record("value <- 1\n");

        let effects =
            try_commit_test_closed_analysis(&mut state, basis, &uri, entry, snapshot, content)
                .expect("current Pending analysis commits");

        assert!(effects.revalidations.is_empty());
        assert_eq!(
            state
                .diagnostics_gate
                .force_republish_count_for_test(&owner),
            1,
            "on-demand enrichment must neither reserve nor consume another pipeline's marker"
        );
    }

    #[test]
    fn stale_non_subject_basis_releases_pending_lease_for_retry() {
        let mut state = WorldState::new();
        let uri = Url::parse("file:///workspace/pending-retry.R").unwrap();
        let claim = match state.workspace_index.claim_enrichment(
            uri.clone(),
            crate::workspace_index::ClosedProvenance::Dynamic,
        ) {
            crate::workspace_index::ClaimEnrichment::Claimed(claim) => claim,
            other => panic!("expected Pending claim, got {other:?}"),
        };
        let basis = state.capture_closed_pending_analysis_basis(claim);
        state.advance_workspace_graph_authority_generation();
        let (entry, snapshot, content) = complete_refresh_test_record("stale <- 1\n");

        assert_eq!(
            try_commit_test_closed_analysis(&mut state, basis, &uri, entry, snapshot, content,),
            Err(crate::state::AnalysisCommitRejected::StaleBasis)
        );
        assert!(state.workspace_index.enrichment_status(&uri).is_none());

        let retry = match state.workspace_index.claim_enrichment(
            uri.clone(),
            crate::workspace_index::ClosedProvenance::Dynamic,
        ) {
            crate::workspace_index::ClaimEnrichment::Claimed(claim) => claim,
            other => panic!("released slot must be reclaimable, got {other:?}"),
        };
        let retry_basis = state.capture_closed_pending_analysis_basis(retry);
        let (entry, snapshot, content) = complete_refresh_test_record("fresh <- 2\n");
        assert!(
            try_commit_test_closed_analysis(
                &mut state,
                retry_basis,
                &uri,
                entry,
                snapshot,
                content,
            )
            .is_ok()
        );
    }

    #[test]
    fn observed_upsert_rejects_absent_pending_and_complete_replacements() {
        let uri = Url::parse("file:///workspace/observed-stale.R").unwrap();

        let mut absent = WorldState::new();
        let basis = absent.capture_closed_removal_analysis_basis(&uri);
        let (replacement, _, _) = complete_refresh_test_record("replacement <- 1\n");
        absent.workspace_index.insert(uri.clone(), replacement);
        let (entry, snapshot, content) = complete_refresh_test_record("stale <- 0\n");
        assert_eq!(
            try_commit_test_closed_analysis(&mut absent, basis, &uri, entry, snapshot, content,),
            Err(crate::state::AnalysisCommitRejected::StaleBasis)
        );
        assert_eq!(
            absent
                .workspace_index
                .get(&uri)
                .unwrap()
                .contents
                .to_string(),
            "replacement <- 1\n"
        );

        let mut pending = WorldState::new();
        let _claim = pending.workspace_index.claim_enrichment(
            uri.clone(),
            crate::workspace_index::ClosedProvenance::Dynamic,
        );
        let basis = pending.capture_closed_removal_analysis_basis(&uri);
        pending.workspace_index.invalidate(&uri);
        let _replacement = pending.workspace_index.claim_enrichment(
            uri.clone(),
            crate::workspace_index::ClosedProvenance::Dynamic,
        );
        let (entry, snapshot, content) = complete_refresh_test_record("stale <- 0\n");
        assert_eq!(
            try_commit_test_closed_analysis(&mut pending, basis, &uri, entry, snapshot, content,),
            Err(crate::state::AnalysisCommitRejected::StaleBasis)
        );
        assert_eq!(
            pending.workspace_index.enrichment_status(&uri),
            Some(crate::workspace_index::EnrichmentStatus::Pending)
        );

        let mut complete = WorldState::new();
        let (old, _, _) = complete_refresh_test_record("old <- 1\n");
        complete.workspace_index.insert(uri.clone(), old);
        let basis = complete.capture_closed_removal_analysis_basis(&uri);
        let (replacement, _, _) = complete_refresh_test_record("replacement <- 2\n");
        complete.workspace_index.insert(uri.clone(), replacement);
        let (entry, snapshot, content) = complete_refresh_test_record("stale <- 0\n");
        assert_eq!(
            try_commit_test_closed_analysis(&mut complete, basis, &uri, entry, snapshot, content,),
            Err(crate::state::AnalysisCommitRejected::StaleBasis)
        );
        assert_eq!(
            complete
                .workspace_index
                .get(&uri)
                .unwrap()
                .contents
                .to_string(),
            "replacement <- 2\n"
        );
    }

    #[test]
    fn observed_upsert_rejects_every_consumed_context_authority_change() {
        let target = Url::parse("file:///workspace/target.R").unwrap();
        let parent = Url::parse("file:///workspace/parent.R").unwrap();

        let mut open = WorldState::new();
        open.open_document(parent.clone(), "parent <- 1\n", Some(1));
        let basis = open.capture_closed_removal_analysis_basis(&target);
        let generation = open.documents.get_record(&parent).unwrap().generation();
        let mut metadata = crate::cross_file::CrossFileMetadata::default();
        metadata.working_directory = Some("/changed".to_string());
        open.replace_open_document_metadata_if_current(&parent, generation, Arc::new(metadata))
            .unwrap();
        let (entry, snapshot, content) = complete_refresh_test_record("stale <- 0\n");
        assert_eq!(
            try_commit_test_closed_analysis(&mut open, basis, &target, entry, snapshot, content,),
            Err(crate::state::AnalysisCommitRejected::StaleBasis)
        );

        let mut closed = WorldState::new();
        let (parent_entry, _, _) = complete_refresh_test_record("parent <- 1\n");
        closed.workspace_index.insert(parent.clone(), parent_entry);
        let basis = closed
            .attach_analysis_context_authorities(
                closed.capture_closed_removal_analysis_basis(&target),
                vec![parent.clone()],
            )
            .unwrap();
        let (replacement, _, _) = complete_refresh_test_record("parent <- 2\n");
        closed.workspace_index.insert(parent, replacement);
        let (entry, snapshot, content) = complete_refresh_test_record("stale <- 0\n");
        assert_eq!(
            try_commit_test_closed_analysis(&mut closed, basis, &target, entry, snapshot, content,),
            Err(crate::state::AnalysisCommitRejected::StaleBasis)
        );

        let mut graph = WorldState::new();
        let basis = graph.capture_closed_removal_analysis_basis(&target);
        graph.apply_prepared_workspace_index(
            Vec::new(),
            Vec::new(),
            crate::cross_file::DependencyGraph::new(),
            HashMap::new(),
            std::collections::HashSet::new(),
        );
        let (entry, snapshot, content) = complete_refresh_test_record("stale <- 0\n");
        assert_eq!(
            try_commit_test_closed_analysis(&mut graph, basis, &target, entry, snapshot, content,),
            Err(crate::state::AnalysisCommitRejected::StaleBasis)
        );
    }

